/* =========================================================
   LOCUS M-PESA DARAJA CONFIGURATION
========================================================= */

const MPESA_CONFIG = {
  environment: String(process.env.MPESA_ENVIRONMENT || 'sandbox').trim().toLowerCase(),
  consumerKey: String(process.env.MPESA_CONSUMER_KEY || '').trim(),
  consumerSecret: String(process.env.MPESA_CONSUMER_SECRET || '').trim(),
  shortcode: String(process.env.MPESA_SHORTCODE || '174379').trim(),
  passkey: String(process.env.MPESA_PASSKEY || '').trim(),
  callbackUrl: String(process.env.MPESA_CALLBACK_URL || '').trim()
};

function getMpesaBaseUrl() {
  if (MPESA_CONFIG.environment === 'production') {
    return 'https://api.safaricom.co.ke';
  }

  return 'https://sandbox.safaricom.co.ke';
}

async function getMpesaAccessToken() {
  if (!MPESA_CONFIG.consumerKey || !MPESA_CONFIG.consumerSecret) {
    throw new Error('MPESA_CREDENTIALS_MISSING');
  }

  const auth = Buffer
    .from(`${MPESA_CONFIG.consumerKey}:${MPESA_CONFIG.consumerSecret}`)
    .toString('base64');

  const response = await fetch(
    `${getMpesaBaseUrl()}/oauth/v1/generate?grant_type=client_credentials`,
    {
      method: 'GET',
      headers: {
        Authorization: `Basic ${auth}`
      }
    }
  );

  const raw = await response.text();

  let data = {};
  try {
    data = raw ? JSON.parse(raw) : {};
  } catch {
    console.error('M-PESA OAUTH NON-JSON RESPONSE:', response.status, raw.slice(0, 500));
    throw new Error(MPESA_OAUTH_INVALID_RESPONSE_);
  }

  if (!response.ok || !data.access_token) {
    console.error('M-PESA OAUTH FAILED:', response.status, JSON.stringify(data));
    throw new Error(data.error_description || data.errorMessage || data.errorCode || MPESA_OAUTH_FAILED_);
  }

  return data.access_token;
}
function normalizeMpesaPhone(phone) {
  let value = String(phone || '').trim().replace(/[^\d+]/g, '');

  if (value.startsWith('+254')) {
    value = value.slice(1);
  }

  if (value.startsWith('07') || value.startsWith('01')) {
    value = '254' + value.slice(1);
  }

  if (!/^254[17]\d{8}$/.test(value)) {
    throw new Error('INVALID_MPESA_PHONE');
  }

  return value;
}

async function sendMpesaStkPush({
  phone,
  amount,
  paymentRequestId
}) {
  if (!MPESA_CONFIG.callbackUrl) {
    throw new Error('MPESA_CALLBACK_URL_MISSING');
  }

  if (!MPESA_CONFIG.shortcode || !MPESA_CONFIG.passkey) {
    throw new Error('MPESA_STK_CONFIGURATION_MISSING');
  }

  const normalizedPhone = normalizeMpesaPhone(phone);

  const numericAmount = Math.round(Number(amount));

  if (!Number.isFinite(numericAmount) || numericAmount < 1) {
    throw new Error('INVALID_MPESA_AMOUNT');
  }

  const timestamp = new Date()
    .toISOString()
    .replace(/\D/g, '')
    .slice(0, 14);

  const password = Buffer
    .from(
      `${MPESA_CONFIG.shortcode}${MPESA_CONFIG.passkey}${timestamp}`
    )
    .toString('base64');

  const token = await getMpesaAccessToken();

  const response = await fetch(
    `${getMpesaBaseUrl()}/mpesa/stkpush/v1/processrequest`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        BusinessShortCode: MPESA_CONFIG.shortcode,
        Password: password,
        Timestamp: timestamp,
        TransactionType: 'CustomerPayBillOnline',
        Amount: numericAmount,
        PartyA: normalizedPhone,
        PartyB: MPESA_CONFIG.shortcode,
        PhoneNumber: normalizedPhone,
        CallBackURL: MPESA_CONFIG.callbackUrl,
        AccountReference: `LOC${paymentRequestId}`,
        TransactionDesc: 'LocusPayment'
      })
    }
  );

  const raw = await response.text();

  let data = {};

  try {
    data = raw ? JSON.parse(raw) : {};
  } catch {
    throw new Error(
      `MPESA_STK_INVALID_RESPONSE_${response.status}`
    );
  }

  if (!response.ok || String(data.ResponseCode || '') !== '0') {
    console.error(
      'M-PESA STK PUSH FAILED:',
      response.status,
      JSON.stringify(data)
    );

    throw new Error(
      data.errorMessage ||
      data.ResponseDescription ||
      data.ResponseCode ||
      'MPESA_STK_PUSH_FAILED'
    );
  }

  return {
    merchantRequestId:
      String(data.MerchantRequestID || '').trim(),

    checkoutRequestId:
      String(data.CheckoutRequestID || '').trim(),

    responseCode:
      String(data.ResponseCode || '').trim(),

    responseDescription:
      String(data.ResponseDescription || '').trim(),

    customerMessage:
      String(data.CustomerMessage || '').trim(),

    phone: normalizedPhone,
    amount: numericAmount
  };
}


function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

