/* =========================================================
   LOCUS USER ID GENERATOR
========================================================= */

function getLocusIdPrefix(user) {
  if (user.role === 'rider') {
    return 'LOC-RID';
  }

  if (user.role === 'dispatcher') {
    return 'LOC-DSP';
  }

  if (user.role === 'customer') {
    return 'LOC-CUS';
  }

  if (user.role === 'admin') {
    const adminType =
      String(user.admin_type || '')
        .trim()
        .toLowerCase();

    if (adminType === 'accounts') {
      return 'LOC-ACC';
    }

    if (adminType === 'finance') {
      return 'LOC-FIN';
    }

    return 'LOC-ADM';
  }

  return 'LOC-USR';
}

function generateLocusId(user) {
  const prefix = getLocusIdPrefix(user);

  const existing = db.prepare(`
    SELECT locus_id
    FROM users
    WHERE locus_id LIKE ?
    ORDER BY id DESC
    LIMIT 1
  `).get(`${prefix}-%`);

  let nextNumber = 1;

  if (existing && existing.locus_id) {
    const match = String(existing.locus_id).match(/-(\d+)$/);

    if (match) {
      nextNumber = Number(match[1]) + 1;
    }
  }

  return `${prefix}-${String(nextNumber).padStart(6, '0')}`;
}

const usersWithoutLocusId = db.prepare(`
  SELECT id, role, admin_type
  FROM users
  WHERE (
    locus_id IS NULL
    OR TRIM(locus_id) = ''
  )
  AND role NOT IN ('rider', 'dispatcher')
`).all();
const assignLocusId = db.prepare(`
  UPDATE users
  SET locus_id=?
  WHERE id=?
`);

for (const user of usersWithoutLocusId) {
  let locusId = generateLocusId(user);

  while (
    db.prepare(`
      SELECT 1
      FROM users
      WHERE locus_id=?
    `).get(locusId)
  ) {
    const prefix = getLocusIdPrefix(user);

    const match = locusId.match(/-(\d+)$/);
    const nextNumber = match
      ? Number(match[1]) + 1
      : 1;

    locusId =
      `${prefix}-${String(nextNumber).padStart(6, '0')}`;
  }

  assignLocusId.run(locusId, user.id);
}
/* =========================================================
   ASSIGN LOCUS ID TO NEW USER
========================================================= */

function assignNewUserLocusId(userId) {
  const user = db.prepare(`
    SELECT id, role, admin_type, locus_id
    FROM users
    WHERE id=?
  `).get(userId);

  if (!user) return;

  if (user.locus_id && String(user.locus_id).trim()) {
    return;
  }

  let locusId = generateLocusId(user);

  while (
    db.prepare(`
      SELECT 1
      FROM users
      WHERE locus_id=?
    `).get(locusId)
  ) {
    const prefix = getLocusIdPrefix(user);
    const match = locusId.match(/-(\d+)$/);
    const nextNumber = match
      ? Number(match[1]) + 1
      : 1;

    locusId =
      `${prefix}-${String(nextNumber).padStart(6, '0')}`;
  }

  db.prepare(`
    UPDATE users
    SET locus_id=?
    WHERE id=?
  `).run(locusId, userId);
}
