  /* =========================================================
     GENERATE DISPATCHER ID
  ========================================================= */

  function generateDispatcherId() {
    const existing = db.prepare(`
      SELECT dispatcher_id
      FROM users
      WHERE dispatcher_id LIKE 'LOC-DSP-%'
      ORDER BY id DESC
      LIMIT 1
    `).get();

    let nextNumber = 1;

    if (existing && existing.dispatcher_id) {
      const match =
        String(existing.dispatcher_id).match(/-(\d+)$/);

      if (match) {
        nextNumber = Number(match[1]) + 1;
      }
    }

    let dispatcherId =
      `LOC-DSP-${String(nextNumber).padStart(6, '0')}`;

    while (
      db.prepare(`
        SELECT 1
        FROM users
        WHERE dispatcher_id=?
      `).get(dispatcherId)
    ) {
      nextNumber += 1;

      dispatcherId =
        `LOC-DSP-${String(nextNumber).padStart(6, '0')}`;
    }

    return dispatcherId;
  }
