/* =========================================================
   SAFARICOM DARAJA STK CALLBACK
========================================================= */

app.post(
  '/mpesa/callback',
  async (req, res) => {
    try {
      const callback =
        req.body &&
        req.body.Body &&
        req.body.Body.stkCallback;

      if (!callback) {
        console.warn(
          'M-PESA CALLBACK: missing stkCallback'
        );

        return res.json({
          ResultCode: 0,
          ResultDesc: 'Accepted'
        });
      }

      const checkoutRequestId =
        String(
          callback.CheckoutRequestID || ''
        ).trim();

      if (!checkoutRequestId) {
        console.warn(
          'M-PESA CALLBACK: missing CheckoutRequestID'
        );

        return res.json({
          ResultCode: 0,
          ResultDesc: 'Accepted'
        });
      }

      const payment =
        db.prepare(`
          SELECT *
          FROM customer_payment_requests
          WHERE checkout_request_id=?
          LIMIT 1
        `).get(checkoutRequestId);

      if (!payment) {

        const businessTopUp =
          db.prepare(`
            SELECT *
            FROM business_wallet_topup_requests
            WHERE checkout_request_id=?
            LIMIT 1
          `).get(checkoutRequestId);

        if (businessTopUp) {

          if (businessTopUp.status === 'paid') {
            return res.json({
              ResultCode: 0,
              ResultDesc: 'Accepted'
            });
          }

          const businessResultCode =
            Number(callback.ResultCode);

          if (businessResultCode !== 0) {

            db.prepare(`
              UPDATE business_wallet_topup_requests
              SET
                status='failed',
                failure_reason=?,
                updated_at=CURRENT_TIMESTAMP
              WHERE
                id=?
                AND status='pending'
            `).run(
              String(
                callback.ResultDesc ||
                'M-Pesa payment was not completed.'
              ).slice(0, 500),
              businessTopUp.id
            );

            return res.json({
              ResultCode: 0,
              ResultDesc: 'Accepted'
            });
          }

          const businessMetadata = {};

          const businessItems =
            callback.CallbackMetadata &&
            Array.isArray(callback.CallbackMetadata.Item)
              ? callback.CallbackMetadata.Item
              : [];

          for (const item of businessItems) {
            if (item && item.Name) {
              businessMetadata[item.Name] = item.Value;
            }
          }

          const mpesaReceipt =
            String(
              businessMetadata.MpesaReceiptNumber || ''
            ).trim() || null;

          db.transaction(() => {

            const updated =
              db.prepare(`
                UPDATE business_wallet_topup_requests
                SET
                  status='paid',
                  provider_reference=?,
                  failure_reason=NULL,
                  updated_at=CURRENT_TIMESTAMP
                WHERE
                  id=?
                  AND status='pending'
              `).run(
                mpesaReceipt,
                businessTopUp.id
              );

            if (updated.changes !== 1) {
              return;
            }

            const walletUpdated =
              db.prepare(`
                UPDATE wallets
                SET
                  balance = balance + ?
                WHERE
                  id=?
                  AND user_id=?
              `).run(
                Number(businessTopUp.amount),
                businessTopUp.wallet_id,
                businessTopUp.business_user_id
              );

            if (walletUpdated.changes !== 1) {
              throw new Error(
                'BUSINESS_WALLET_UPDATE_FAILED'
              );
            }

            db.prepare(`
              INSERT INTO business_wallet_transactions (
                business_wallet_id,
                business_user_id,
                type,
                amount,
                description,
                reference,
                phone
              )
              VALUES (?, ?, 'top_up', ?, ?, ?, ?)
            `).run(
              businessTopUp.wallet_id,
              businessTopUp.business_user_id,
              Number(businessTopUp.amount),
              'Business wallet top-up',
              mpesaReceipt ||
                `TOPUP-${businessTopUp.id}`,
              businessTopUp.phone
            );

          })();

          return res.json({
            ResultCode: 0,
            ResultDesc: 'Accepted'
          });
        }

        console.warn(
          'M-PESA CALLBACK: unknown CheckoutRequestID:',
          checkoutRequestId
        );

        return res.json({
          ResultCode: 0,
          ResultDesc: 'Accepted'
        });
      }

      /*
        Ignore duplicate callbacks after the
        payment has already produced an order.
      */

      if (
        payment.status === 'paid' &&
        payment.order_id
      ) {
        return res.json({
          ResultCode: 0,
          ResultDesc: 'Accepted'
        });
      }

      const resultCode =
        Number(callback.ResultCode);

      if (resultCode !== 0) {
        db.prepare(`
          UPDATE customer_payment_requests
          SET
            status='failed',
            failure_reason=?,
            updated_at=CURRENT_TIMESTAMP
          WHERE
            id=?
            AND status='pending'
        `).run(
          String(
            callback.ResultDesc ||
            'M-Pesa payment was not completed.'
          ).slice(0, 500),
          payment.id
        );

        return res.json({
          ResultCode: 0,
          ResultDesc: 'Accepted'
        });
      }

      const metadata = {};
      const items =
        callback.CallbackMetadata &&
        Array.isArray(callback.CallbackMetadata.Item)
          ? callback.CallbackMetadata.Item
          : [];

      for (const item of items) {
        if (item && item.Name) {
          metadata[item.Name] = item.Value;
        }
      }

      const freshPayment =
        db.prepare(`
          SELECT *
          FROM customer_payment_requests
          WHERE id=?
        `).get(payment.id);

      if (
        freshPayment &&
        freshPayment.status === 'pending' &&
        !freshPayment.order_id
      ) {
        let payload;

        try {
          payload =
            JSON.parse(
              freshPayment.request_payload || '{}'
            );
        } catch {
          throw new Error(
            'PAYMENT_REQUEST_PAYLOAD_INVALID'
          );
        }

        const result =
          db.transaction(() => {

            db.prepare(`
              UPDATE customer_payment_requests
              SET
                status='paid',
                provider_reference=?,
                failure_reason=NULL,
                updated_at=CURRENT_TIMESTAMP
              WHERE
                id=?
                AND status='pending'
            `).run(
              String(
                metadata.MpesaReceiptNumber || ''
              ).trim() || null,
              freshPayment.id
            );

            const existing =
              db.prepare(`
                SELECT
                  id,
                  order_number,
                  status
                FROM orders
                WHERE
                  customer_id=?
                  AND status NOT IN (
                    'delivered',
                    'cancelled'
                  )
                ORDER BY id DESC
                LIMIT 1
              `).get(
                freshPayment.customer_id
              );

            if (existing) {
              throw new Error(
                'ACTIVE_ORDER_EXISTS'
              );
            }

            const orderNumber =
              'LOC-' +
              Date.now()
                .toString()
                .slice(-8);

            const deliveryOtp =
              crypto
                .randomInt(
                  100000,
                  1000000
                )
                .toString();

            const orderResult =
              db.prepare(`
                INSERT INTO orders (
                  customer_id,
                  service,
                  pickup,
                  dropoff,
                  pickup_latitude,
                  pickup_longitude,
                  dropoff_latitude,
                  dropoff_longitude,
                  amount,
                  rider_earnings,
                  order_number,
                  delivery_otp,
                  payment_method,
                   customer_payment_reference,
                   customer_payment_submitted_at,
                   errand_type,
                  errand_description,
                  errand_amount,
                  business_request_timing,
                  scheduled_at,
                  status
                )
                VALUES (
                  ?, ?, ?, ?, ?, ?,
                  ?, ?, ?, ?, ?, ?,
                  ?, ?, ?, ?, ?, ?,
                  ?, ?, ?
                )
              `).run(
                freshPayment.customer_id,
                payload.service,
                payload.pickup,
                payload.dropoff,
                payload.pickupLatitude,
                payload.pickupLongitude,
                payload.dropoffLatitude,
                payload.dropoffLongitude,
                Number(payload.totalAmount),
                Number(payload.riderEarnings),
                orderNumber,
                deliveryOtp,
                freshPayment.payment_method || 'mpesa',
                payload.errandType || null,
                payload.errandDescription || null,
                Number(payload.errandAmount || 0),
                payload.requestTiming,
                payload.requestTiming === 'scheduled'
                  ? payload.scheduledAt
                  : null,
                payload.requestTiming === 'scheduled'
                  ? 'scheduled'
                  : 'pending'
              );

            const orderId =
              Number(
                orderResult.lastInsertRowid
              );

            db.prepare(`
              INSERT INTO financial_transactions (
                order_id,
                customer_id,
                rider_id,
                customer_amount,
                rider_earnings,
                locus_earnings,
                customer_payment_status,
                rider_payment_status,
                rider_debt_status
              )
              VALUES (
                ?,
                ?,
                NULL,
                ?,
                ?,
                ?,
                'paid',
                'unpaid',
                'none'
              )
            `).run(
              orderId,
              freshPayment.customer_id,
              Number(payload.totalAmount),
              Number(payload.riderEarnings),
              Number(payload.locusEarnings)
            );

            db.prepare(`
              UPDATE customer_payment_requests
              SET
                order_id=?,
                updated_at=CURRENT_TIMESTAMP
              WHERE id=?
                AND order_id IS NULL
            `).run(
              orderId,
              freshPayment.id
            );

            return {
              orderId,
              requestTiming:
                payload.requestTiming
            };
          })();

        if (
          result.requestTiming === 'immediate'
        ) {
          dispatchOrder(result.orderId);
        }
      }

      return res.json({
        ResultCode: 0,
        ResultDesc: 'Accepted'
      });

    } catch (error) {
      console.error(
        'M-PESA CALLBACK PROCESSING ERROR:',
        error
      );

      /*
        Always acknowledge the Safaricom callback.
        The error is logged for server-side diagnosis.
      */

      return res.json({
        ResultCode: 0,
        ResultDesc: 'Accepted'
      });
    }
  }
);

