app.get(
  '/api/sound-notifications',
 requireAuth,
  (req, res) => {

    const userId =
      Number(req.session.user.id);

    const role =
      String(req.session.user.role || '');

    const result = {
      messages: 0,
      rider_notifications: 0,
      order_events: 0
    };

    const latestMessage =
      db.prepare(`
        SELECT id
        FROM messages
        WHERE recipient_id=?
        ORDER BY id DESC
        LIMIT 1
      `).get(userId);

    if (latestMessage) {
      result.messages =
        Number(latestMessage.id);
    }

    if (role === 'rider') {

      const latestRiderNotification =
        db.prepare(`
          SELECT id
          FROM rider_notifications
          WHERE
            active=1
            AND (rider_id=? OR rider_id IS NULL)
          ORDER BY id DESC
          LIMIT 1
        `).get(userId);

      if (latestRiderNotification) {
        result.rider_notifications =
          Number(latestRiderNotification.id);
      }
    }

    if (role === 'customer') {

      const latestOrderEvent =
        db.prepare(`
          SELECT oe.id
          FROM order_events oe
          INNER JOIN orders o
            ON o.id=oe.order_id
          WHERE
            o.customer_id=?
            AND oe.event IN (
              'dispatched',
              'accepted',
              'arrived_at_pickup',
              'picked_up',
              'on_the_way',
              'arrived_at_dropoff',
              'payment_collected',
              'delivered'
            )
          ORDER BY oe.id DESC
          LIMIT 1
        `).get(userId);

      if (latestOrderEvent) {
        result.order_events =
          Number(latestOrderEvent.id);
      }
    }

    res.json(result);
  }
);

