/* =========================================================
   NOMINATIM LOCATION SEARCH PROXY
========================================================= */

app.get(
  '/nominatim/search',
  async (req, res) => {
    try {
      const params = new URLSearchParams();

      for (const [key, value] of Object.entries(req.query)) {
        if (value !== undefined && value !== null) {
          params.set(key, String(value));
        }
      }

      const url =
        'https://nominatim.openstreetmap.org/search?' +
        params.toString();

      const response = await fetch(url, {
        headers: {
          'Accept': 'application/json',
          'User-Agent': 'Locus Delivery Solution/1.0'
        }
      });

      if (!response.ok) {
        return res
          .status(response.status)
          .json({
            error: 'Location search failed.'
          });
      }

      const data = await response.json();

      res.json(data);
    } catch (error) {
      console.error(
        'Nominatim proxy error:',
        error
      );

      res.status(500).json({
        error: 'Unable to search locations right now.'
      });
    }
  }
);
/* =========================================================
   ADMIN PROTECTED RIDER DOCUMENT VIEW
========================================================= */

app.get(
  '/admin/user-document/:userId/:document',
  requireRole('admin'),
  (req, res) => {

    const userId = Number(req.params.userId);
    const document = String(req.params.document || '').trim();

    if (!Number.isInteger(userId)) {
      return res.status(400).send('Invalid user.');
    }

    const allowedDocuments = {
      id: 'id_document_path',
      profile: 'profile_photo_path',
      police: 'police_clearance_path',
      license: 'driving_license_path',
      insurance: 'motorcycle_insurance_path'
    };

    const column = allowedDocuments[document];

    if (!column) {
      return res.status(404).send('Document not found.');
    }

    const user = db.prepare(`
      SELECT
        id,
        role,
        ${column} AS document_path
      FROM users
      WHERE id=?
    `).get(userId);

    if (!user || user.role !== 'rider') {
      return res.status(404).send('Rider not found.');
    }

    if (!user.document_path) {
      return res.status(404).send('Document has not been uploaded.');
    }

    const uploadsRoot = path.resolve(
      __dirname,
      'uploads',
      'riders'
    );

    const documentPath = path.resolve(
      user.document_path
    );

    if (
      !documentPath.startsWith(
        uploadsRoot + path.sep
      )
    ) {
      return res.status(403).send('Invalid document path.');
    }

    if (!fs.existsSync(documentPath)) {
      return res.status(404).send('Document file not found.');
    }

    /*
      Uploaded rider files are stored by Multer without
      their original file extension.

      Detect the file type from its contents so the browser
      displays images/PDFs instead of treating them as text.
    */

    const buffer = fs.readFileSync(documentPath);

    let contentType = 'application/octet-stream';

    if (
      buffer.length >= 8 &&
      buffer[0] === 0x89 &&
      buffer[1] === 0x50 &&
      buffer[2] === 0x4e &&
      buffer[3] === 0x47
    ) {
      contentType = 'image/png';

    } else if (
      buffer.length >= 3 &&
      buffer[0] === 0xff &&
      buffer[1] === 0xd8 &&
      buffer[2] === 0xff
    ) {
      contentType = 'image/jpeg';

    } else if (
      buffer.length >= 5 &&
      buffer.slice(0, 5).toString('ascii') === '%PDF-'
    ) {
      contentType = 'application/pdf';
    }

    res.set('Content-Type', contentType);
    res.set('Content-Disposition', 'inline');

    res.sendFile(documentPath);
  }
);


