app.post(
  '/login',
  authLimit,
  csrfCheck,
  (req, res) => {

    const parsed =
      loginSchema.safeParse(req.body);

    if (!parsed.success) {
      return res.status(400).send(
        page(
          'Login',
          `
          <div class="card">
            ${alertBox(
            'Invalid login details.'
          )}

            <a
              class="btn"
              href="/login"
            >
              Try again
            </a>
          </div>
          `,
          req
        )
      );
    }

    const {
      email,
      password
    } = parsed.data;

    const u = db
      .prepare(`
        SELECT *
        FROM users
        WHERE email=?
      `)
      .get(
        email.toLowerCase()
      );

    if (
      !u ||
      !bcrypt.compareSync(
        password,
        u.password_hash
      )
    ) {
      return res.status(401).send(
        page(
          'Login',
          `
          <div class="card">
            ${alertBox(
            'Incorrect email or password.'
          )}

            <a
              class="btn"
              href="/login"
            >
              Try again
            </a>
          </div>
          `,
          req
        )
      );
    }
    if (
      u.role === 'rider' &&
      (u.approval_status || 'approved') !== 'approved'
    ) {
      if (Number(u.active) !== 1) {
        return res.status(403).send(
          page(
            'Account Deactivated',
            `
          <div class="card">

            <div class="pill">
              LOCUS ACCOUNT
            </div>

            <h1>
              Account Deactivated
            </h1>

            <p>
              This Locus account has been deactivated and
              can no longer be used to log in.
            </p>

            <p class="muted">
              If you believe this was done in error,
              please contact Locus administration.
            </p>

            <a
              class="btn"
              href="/login"
            >
              Back to Login
            </a>

          </div>
          `,
            req
          )
        );
      }

      const statusMessage =
        (u.approval_status || 'pending') === 'rejected'
          ? 'Your rider application was not approved. Please contact Locus administration.'
          : 'Your rider application has been received and is awaiting Locus administration approval.';

      return res.status(403).send(
        page(
          'Application status',
          `
          <div class="card">

            <div class="pill">
              LOCUS RIDER APPLICATION
            </div>

            <h1>
              Application awaiting approval
            </h1>

            <p>
              ${statusMessage}
            </p>

            <p class="muted">
              Your documents must be reviewed and approved
              by Locus administration before you can access
              the rider platform.
            </p>

            <a
              class="btn"
              href="/login"
            >
              Back to login
            </a>

          </div>
          `,
          req
        )
      );
    }
    /*
      Destroy the previous authenticated session
      and create a completely fresh session.
    */

    req.session.regenerate(err => {

      if (err) {
        return res
          .status(500)
          .send('Server error');
      }

      req.session.user = {
        id: u.id,
        name: u.name,
        role: u.role,
        email: u.email,
        admin_type: u.admin_type || null
      };
      req.session.csrf =
        crypto.randomBytes(32).toString('hex');

      if (u.role === 'customer') {
        return res.redirect('/customer');
      }

if (u.role === 'rider') {
  return res.redirect('/rider');
}

if (u.role === 'business') {
  return res.redirect('/business');
}
      if (u.role === 'admin' && u.admin_type === 'accounts') {
        return res.redirect('/accounts');
      }

      if (u.role === 'admin' && u.admin_type === 'finance') {
        return res.redirect('/finance');
      }

      if (u.role === 'admin') {
        return res.redirect('/admin');
      }

      if (u.role === 'finance') {
        return res.redirect('/finance');
      }

      return res.redirect('/dashboard');
    });
  }
);

/* =========================================================
   LOGOUT
========================================================= */

app.post(
  '/logout',
  csrfCheck,
  (req, res) => {

    req.session.destroy(err => {

      res.clearCookie('locus.sid', {
        httpOnly: true,
        sameSite: 'lax',
        secure:
          process.env.NODE_ENV === 'production'
      });

      if (err) {
        return res.status(500).send(
          page(
            'Logout',
            `
            <div class="card">
              <h1>Logout failed</h1>

              <p>
                Please close the browser
                and try again.
              </p>
            </div>
            `,
            req
          )
        );
      }

      res.redirect('/login');
    });
  }
);

