app.get(
  '/dashboard',
  requireAuth,
  (req, res) => {

    const u = req.session.user;

    let target = '/';

    if (u.role === 'customer') {
      target = '/customer';
    }

    if (u.role === 'rider') {
      target = '/rider';
    }
    if (u.role === 'admin') {
      target = '/admin';
    }

    if (u.role === 'dispatcher') {
      target = '/dispatcher';
    }

    res.send(
      page(
        'Dashboard',

        `
        <div class="card dashboard-head">

          <div>

            <div class="pill">
              ${e(u.role.toUpperCase())}
            </div>

            <h1>
              Welcome, ${e(u.name)}
            </h1>

            <p>
              Your Locus workspace is ready.
            </p>

          </div>

          <a
            class="btn"
            href="${target}"
          >
            Open ${e(u.role)} dashboard
          </a>

        </div>

        <section class="grid three">

          <div class="stat">
            <span>Account</span>
            <strong>
              ${e(u.role)}
            </strong>
          </div>

          <div class="stat">
            <span>Status</span>
            <strong>
              Active
            </strong>
          </div>

          <div class="stat">
            <span>Security</span>
            <strong>
              Protected
            </strong>
          </div>

        </section>
        `,
        req
      )
    );
  }
);

