app.get(
  '/customer/support',
  requireRole('customer'),
  (req, res) => {

    const errandServiceFee =
      Number(getLocusSetting('errand_service_fee', 500));

    const customerId = req.session.user.id;

    const assignment = db.prepare(`
      SELECT
        dca.dispatcher_id,
        u.name AS dispatcher_name
      FROM dispatcher_chat_assignments dca
      INNER JOIN users u
        ON u.id=dca.dispatcher_id
      WHERE dca.chat_user_id=?
        AND u.role='dispatcher'
        AND u.active=1
    `).get(customerId);

    const messages = db.prepare(`
      SELECT
        m.id,
        m.sender_id,
        m.recipient_id,
        m.message,
        m.read_at,
        m.created_at,
        s.name AS sender_name,
        s.role AS sender_role
      FROM messages m
      LEFT JOIN users s
        ON s.id=m.sender_id
      WHERE
        (
          m.sender_id=?
          AND m.recipient_id=(SELECT dispatcher_id FROM dispatcher_chat_assignments WHERE chat_user_id=?)
        )
        OR
        (
          m.recipient_id=?
          AND m.sender_id=(SELECT dispatcher_id FROM dispatcher_chat_assignments WHERE chat_user_id=?)
        )
      ORDER BY m.id ASC
    `).all(customerId, customerId, customerId, customerId);

    db.prepare(`
      UPDATE messages
      SET read_at=CURRENT_TIMESTAMP
      WHERE
        sender_id=(SELECT dispatcher_id FROM dispatcher_chat_assignments WHERE chat_user_id=?) AND recipient_id=?
        AND read_at IS NULL
    `).run(customerId, customerId);

    const messageRows = messages.map(m => `
      <div style="
        margin-bottom:10px;
        padding:10px 12px;
        border-radius:10px;
        background:${Number(m.sender_id) === Number(customerId) ? '#000000' : '#f7f7f7'};
      ">
        <strong>${e(m.sender_name || (Number(m.sender_id) === Number(customerId) ? 'You' : 'Dispatcher'))}</strong>
        <div style="margin-top:4px; white-space:pre-wrap;">${e(m.message)}</div>
        <small style="display:block; margin-top:5px; color:#6b7280;">
          ${e(m.created_at || '')}
        </small>
      </div>
    `).join('');

    res.send(`<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Locus Support</title>
  <link rel="stylesheet" href="/style.css">
</head>

<body>

  <main class="container" style="max-width:760px; margin:0 auto; padding:20px;">

    <div class="page-head">
      <div>
        <div class="pill">LOCUS SUPPORT</div>
        <h1>Customer Support</h1>
        <p style="color:#6b7280;">
          ${assignment
            ? `Connected to ${e(assignment.dispatcher_name || 'Locus Dispatcher')}`
            : 'Send a message to Locus Dispatch Support.'}
        </p>
      </div>
    </div>

    <div class="card" style="margin-top:16px;">

      <div style="
        max-height:460px;
        overflow-y:auto;
        margin-bottom:16px;
      ">
        ${messageRows || `
          <div style="
            padding:20px;
            text-align:center;
            color:#000000;
          ">
            No messages yet. Send a message below to contact Locus Support.
          </div>
        `}
      </div>

      <form method="POST" action="/customer/support">

        <input
          type="hidden"
          name="_csrf"
          value="${csrf(req)}"
        >

        <label for="customerSupportMessage">
          Message
        </label>

        <textarea
          id="customerSupportMessage"
          name="message"
          rows="4"
          maxlength="2000"
          required
          placeholder="Describe how we can help..."
          style="width:100%; margin-top:6px;"
        ></textarea>

        <button
          type="submit"
          class="btn"
          style="margin-top:10px;"
        >
          Send Message
        </button>

      </form>

    </div>

    <div style="margin-top:16px;">
      <a class="btn ghost" href="/customer">Back to Customer Dashboard</a>
    </div>

  </main>

</body>
</html>`);
  }
);

app.post(
  '/customer/support',
  csrfCheck,
  requireRole('customer'),
  (req, res) => {

    const errandServiceFee =
      Number(getLocusSetting('errand_service_fee', 500));

    const customerId = req.session.user.id;
    const message = String(req.body.message || '').trim();

    if (
      message.length < 1 ||
      message.length > 2000
    ) {
      return res.redirect('/customer/support');
    }

    let assignment = db.prepare(`
      SELECT dispatcher_id
      FROM dispatcher_chat_assignments
      WHERE chat_user_id=?
    `).get(customerId);

    if (!assignment) {

      const dispatcher = db.prepare(`
        SELECT id
        FROM users
        WHERE role='dispatcher'
          AND active=1
        ORDER BY name ASC
        LIMIT 1
      `).get();

      if (!dispatcher) {
        return res.status(503).send(
          'Locus Support is currently unavailable. Please try again later.'
        );
      }

      db.prepare(`
        INSERT OR IGNORE INTO dispatcher_chat_assignments(
          chat_user_id,
          dispatcher_id
        )
        VALUES(?,?)
      `).run(
        customerId,
        dispatcher.id
      );

      assignment = db.prepare(`
        SELECT dispatcher_id
        FROM dispatcher_chat_assignments
        WHERE chat_user_id=?
      `).get(customerId);
    }

    const dispatcherId = Number(assignment?.dispatcher_id || 0);

    if (!dispatcherId) {
      return res.redirect('/customer/support');
    }

    db.prepare(`
      INSERT INTO messages(
        sender_id,
        recipient_id,
        message
      )
      VALUES(?,?,?)
    `).run(
      customerId,
      dispatcherId,
      message
    );

    res.redirect('/customer/support');
  }
);
