app.post(
  '/customer/password',
  csrfCheck,
  requireRole('customer'),
  (req, res) => {

    const errandServiceFee =
      Number(getLocusSetting('errand_service_fee', 500));

    const {
      current_password,
      new_password,
      confirm_password
    } = req.body;

    if (
      !current_password ||
      !new_password ||
      !confirm_password
    ) {
      return res.status(400).send(
        page(
          'Password & Security',
          `
          <div class="card narrow">

            ${alertBox(
            'Please complete all password fields.'
          )}

            <a
              class="btn"
              href="/customer/password"
            >
              Try Again
            </a>

          </div>
          `,
          req
        )
      );
    }

    if (new_password !== confirm_password) {
      return res.status(400).send(
        page(
          'Password & Security',
          `
          <div class="card narrow">

            ${alertBox(
            'The new passwords do not match.'
          )}

            <a
              class="btn"
              href="/customer/password"
            >
              Try Again
            </a>

          </div>
          `,
          req
        )
      );
    }

    if (new_password.length < 8) {
      return res.status(400).send(
        page(
          'Password & Security',
          `
          <div class="card narrow">

            ${alertBox(
            'New password must be at least 8 characters long.'
          )}

            <a
              class="btn"
              href="/customer/password"
            >
              Try Again
            </a>

          </div>
          `,
          req
        )
      );
    }

    if (current_password === new_password) {
      return res.status(400).send(
        page(
          'Password & Security',
          `
          <div class="card narrow">

            ${alertBox(
            'Your new password must be different from your current password.'
          )}

            <a
              class="btn"
              href="/customer/password"
            >
              Try Again
            </a>

          </div>
          `,
          req
        )
      );
    }

    const customer = db.prepare(`
      SELECT
        id,
        password_hash
      FROM users
      WHERE id=?
        AND role='customer'
        AND deleted_at IS NULL
    `).get(req.session.user.id);

    if (!customer) {
      return res.status(404).send(
        page(
          'Password & Security',
          `
          <div class="card narrow">

            ${alertBox(
            'Customer account not found.'
          )}

            <a
              class="btn"
              href="/logout"
            >
              Return to Login
            </a>

          </div>
          `,
          req
        )
      );
    }

    const validPassword = bcrypt.compareSync(
      current_password,
      customer.password_hash
    );

    if (!validPassword) {
      return res.status(400).send(
        page(
          'Password & Security',
          `
          <div class="card narrow">

            ${alertBox(
            'Current password is incorrect.'
          )}

            <a
              class="btn"
              href="/customer/password"
            >
              Try Again
            </a>

          </div>
          `,
          req
        )
      );
    }

    const newHash = bcrypt.hashSync(
      new_password,
      12
    );

    db.prepare(`
      UPDATE users
      SET password_hash=?
      WHERE id=?
        AND role='customer'
        AND deleted_at IS NULL
    `).run(
      newHash,
      customer.id
    );

    res.send(
      page(
        'Password Changed',
        `
        <div class="card narrow">

          <div class="pill">
            LOCUS SECURITY
          </div>

          <h1>
            Password Changed
          </h1>

          <p class="muted">
            Your Locus customer account password has been successfully updated.
          </p>

          <div
            style="
              margin-top:20px;
              padding:15px;
              border-radius:14px;
              background:#ecfdf3;
              border:1px solid #bbf7d0;
              color:#166534;
              font-weight:700;
            "
          >
            Your password has been changed successfully.
          </div>

          <div
            style="
              display:flex;
              flex-wrap:wrap;
              gap:10px;
              margin-top:20px;
            "
          >

            <a
              class="btn"
              href="/customer/profile"
            >
              Back to Profile
            </a>

            <a
              class="btn"
              href="/customer"
            >
              Dashboard
            </a>

          </div>

        </div>
        `,
        req
      )
    );
  }
);


/* =========================================================
   CUSTOMER DELETE ACCOUNT
========================================================= */

app.post(
  '/customer/delete-account',
  csrfCheck,
  requireRole('customer'),
  (req, res) => {

    const errandServiceFee =
      Number(getLocusSetting('errand_service_fee', 500));

    const customerId = req.session.user.id;

    const customer = db.prepare(`
      SELECT
        id,
        role,
        deleted_at
      FROM users
      WHERE id=?
        AND role='customer'
    `).get(customerId);

    if (!customer) {
      return res.status(404).send(
        page(
          'Delete Account',
          `
          <div class="card narrow">

            ${alertBox(
            'Customer account not found.'
          )}

            <a
              class="btn"
              href="/customer"
            >
              Back to Dashboard
            </a>

          </div>
          `,
          req
        )
      );
    }

    if (customer.deleted_at) {
      return res.redirect('/logout');
    }

    /*
      Soft-delete the customer account.

      Historical orders and financial records remain
      available for Locus operational records.
    */

    db.prepare(`
      UPDATE users
      SET
        active=0,
        approval_status='deleted',
        suspension_reason=NULL,
        deleted_at=CURRENT_TIMESTAMP
      WHERE id=?
        AND role='customer'
        AND deleted_at IS NULL
    `).run(customerId);

    req.session.destroy(() => {
      res.send(
        page(
          'Account Deleted',
          `
          <div class="card narrow">

            <div class="pill">
              LOCUS ACCOUNT
            </div>

            <h1>
              Account Deleted
            </h1>

            <p class="muted">
              Your Locus customer account has been permanently deactivated.
            </p>

            <div
              style="
                margin-top:20px;
                padding:15px;
                border-radius:14px;
                background:#fef2f2;
                border:1px solid #fecaca;
                color:#991b1b;
                font-weight:700;
              "
            >
              Your account is no longer active and you have been signed out.
            </div>

            <div style="margin-top:20px;">

              <a
                class="btn"
                href="/login"
              >
                Return to Login
              </a>

            </div>

          </div>
          `,
          req
        )
      );
    });
  }
);
/* =========================================================
   CUSTOMER NEW ORDER
========================================================= */
app.post(
  '/customer/order/:orderId/cancel',
  requireRole('customer'),
  (req, res) => {

    const errandServiceFee =
      Number(getLocusSetting('errand_service_fee', 500));

  if (
  !req.body._csrf ||
  !req.session.csrf ||
  !crypto.timingSafeEqual(
    Buffer.from(req.body._csrf),
    Buffer.from(req.session.csrf)
  )
) {
  return res.status(403).send(
    page(
      'Cancel Order',
      `
      <div class="card">
        ${alertBox(
          'Invalid security token. Please refresh the page and try again.'
        )}

        <a
          class="btn"
          href="/customer/orders"
        >
          Back to Orders
        </a>
      </div>
      `,
      req
    )
  );
}
    const orderId =
      Number(req.params.orderId);

    if (
      !Number.isInteger(orderId) ||
      orderId <= 0
    ) {
      return res.status(400).send(
        page(
          'Cancel Order',
          `
          <div class="card">
            ${alertBox(
              'Invalid order.'
            )}

            <a
              class="btn"
              href="/customer/orders"
            >
              Back to Orders
            </a>
          </div>
          `,
          req
        )
      );
    }

    const order =
      db.prepare(`
        SELECT *
        FROM orders
        WHERE
          id=?
          AND customer_id=?
        LIMIT 1
      `).get(
        orderId,
        req.session.user.id
      );

    if (!order) {
      return res.status(404).send(
        page(
          'Cancel Order',
          `
          <div class="card">
            ${alertBox(
              'Order not found.'
            )}

            <a
              class="btn"
              href="/customer/orders"
            >
              Back to Orders
            </a>
          </div>
          `,
          req
        )
      );
    }

    /*
      Customer cancellation is allowed only
      before the rider confirms arrival at pickup.
    */
    if (
      order.picked_up_at ||
      order.status === 'arrived_at_pickup' ||
      order.status === 'picked_up' ||
      order.status === 'on_the_way' ||
      order.status === 'arrived_at_dropoff' ||
      order.status === 'delivered'
    ) {
      return res.status(400).send(
        page(
          'Cancel Order',
          `
          <div class="card">
            ${alertBox(
              'This order cannot be cancelled now. Please contact the Locus Help Center.'
            )}

            <a
              class="btn"
              href="/customer/orders"
            >
              Back to Orders
            </a>
          </div>
          `,
          req
        )
      );
    }

    if (order.status === 'cancelled') {
      return res.status(400).send(
        page(
          'Cancel Order',
          `
          <div class="card">
            ${alertBox(
              'This order has already been cancelled.'
            )}

            <a
              class="btn"
              href="/customer/orders"
            >
              Back to Orders
            </a>
          </div>
          `,
          req
        )
      );
    }
const customerCancellationReasons = {
  change_of_plans:
    'Change of plans',

  ordered_by_mistake:
    'Order placed by mistake',

  delivery_no_longer_needed:
    'Delivery no longer needed',

  wrong_pickup_or_dropoff:
    'Wrong pickup or drop-off details',

  other:
    'Other'
};

const cancellationReasonKey =
  String(
    req.body.cancel_reason || ''
  ).trim();

if (
  !Object.prototype.hasOwnProperty.call(
    customerCancellationReasons,
    cancellationReasonKey
  )
) {
  return res.status(400).send(
    page(
      'Cancel Order',
      `
      <div class="card">
        ${alertBox(
          'Please select a valid cancellation reason.'
        )}

        <a
          class="btn"
          href="/customer/orders"
        >
          Back to Orders
        </a>
      </div>
      `,
      req
    )
  );
}

const cancellationReason =
  customerCancellationReasons[
    cancellationReasonKey
  ];
    /*
      Calculate the Locus delivery/service portion
      of this order.

      For Shopping and Errand, this deliberately
      excludes the customer's goods/purchase amount.
    */
    const financialTransaction =
      db.prepare(`
        SELECT
          rider_earnings,
          locus_earnings,
          customer_payment_status
        FROM financial_transactions
        WHERE order_id=?
        LIMIT 1
      `).get(order.id);

    const locusServiceAmount =
      financialTransaction
        ? Number(
            financialTransaction.rider_earnings || 0
          ) +
          Number(
            financialTransaction.locus_earnings || 0
          )
        : 0;

    const cancellationCharge =
      Number(
        (locusServiceAmount * 0.5).toFixed(2)
      );
      const cancellationEarnings =
  calculateEarnings(
    cancellationCharge
  );

const cancellationRiderEarnings =
  order.rider_id
    ? Number(
        cancellationEarnings.rider
      )
    : 0;

const cancellationLocusEarnings =
  Number(
    (
      cancellationCharge -
      cancellationRiderEarnings
    ).toFixed(2)
  );
    const cancelTransaction =
      db.prepare(`
        SELECT
          customer_amount,
          customer_payment_status,
          rider_earnings,
          locus_earnings
        FROM financial_transactions
        WHERE order_id=?
        LIMIT 1
      `).get(order.id);

    if (!cancelTransaction) {
      return res.status(400).send(
        page(
          'Cancel Order',
          `
          <div class="card">
            ${alertBox(
              'This order cannot be cancelled because its payment record could not be found. Please contact the Locus Help Center.'
            )}

            <a
              class="btn"
              href="/customer/orders"
            >
              Back to Orders
            </a>
          </div>
          `,
          req
        )
      );
    }

    const originalCustomerAmount =
      Number(
        cancelTransaction.customer_amount || 0
      );

    const refundAmount =
      Math.max(
        0,
        Number(
          (
            originalCustomerAmount -
            cancellationCharge
          ).toFixed(2)
        )
      );

const cancelTransactionUpdate =
  db.prepare(`
    UPDATE financial_transactions
    SET
      customer_amount=?,
      rider_id=?,
      rider_earnings=?,
      locus_earnings=?,
      customer_payment_status=?,
      updated_at=CURRENT_TIMESTAMP
    WHERE
      order_id=?
  `);

const cancelOrderUpdate =
  db.prepare(`
    UPDATE orders
    SET
      status='cancelled',
      cancellation_reason=?,
      cancelled_by='customer',
      cancelled_at=CURRENT_TIMESTAMP,
      updated_at=CURRENT_TIMESTAMP
    WHERE
      id=?
      AND customer_id=?
      AND picked_up_at IS NULL
  `);

    const customerWallet =
      db.prepare(`
        SELECT
          id,
          balance
        FROM wallets
        WHERE user_id=?
        LIMIT 1
      `).get(
        req.session.user.id
      );
const riderWallet =
  order.rider_id
    ? db.prepare(`
        SELECT
          id,
          balance
        FROM wallets
        WHERE user_id=?
        LIMIT 1
      `).get(
        order.rider_id
      )
    : null;
    if (
      cancelTransaction.customer_payment_status ===
        'paid' &&
      refundAmount > 0
    ) {
      if (!customerWallet) {
        return res.status(400).send(
          page(
            'Cancel Order',
            `
            <div class="card">
              ${alertBox(
                'The customer wallet could not be found, so the cancellation cannot be completed. Please contact the Locus Help Center.'
              )}

              <a
                class="btn"
                href="/customer/orders"
              >
                Back to Orders
              </a>
            </div>
            `,
            req
          )
        );
      }
    }

    const cancelReference =
      'CANCEL-' +
      String(order.id) +
      '-' +
      Date.now();

    const cancelTransactionInsert =
      db.prepare(`
        INSERT INTO wallet_transactions (
          wallet_id,
          order_id,
          type,
          amount,
          description,
          reference
        )
        VALUES (
          ?,
          ?,
          'adjustment',
          ?,
          ?,
          ?
        )
      `);

    const performCancellation =
      db.transaction(() => {

if (
  cancelOrderUpdate.run(
    cancellationReason,
    order.id,
    req.session.user.id
  )
  .changes !== 1
)
        {
          throw new Error(
            'CANCELLATION_CONFLICT'
          );
        }

        if (
          cancelTransaction.customer_payment_status ===
            'paid'
        ) {
          if (refundAmount > 0) {
            db.prepare(`
              UPDATE wallets
              SET
                balance=balance+?,
                updated_at=CURRENT_TIMESTAMP
              WHERE
                id=?
            `).run(
              refundAmount,
              customerWallet.id
            );

            cancelTransactionInsert.run(
              customerWallet.id,
              order.id,
              refundAmount,
              'Cancellation refund',
              cancelReference
            );
          }
        }
if (
  cancellationRiderEarnings > 0
) {
  if (!riderWallet) {
    throw new Error(
      'RIDER_WALLET_NOT_FOUND'
    );
  }

  db.prepare(`
    UPDATE wallets
    SET
      balance = balance + ?,
      total_earned = total_earned + ?,
      updated_at = CURRENT_TIMESTAMP
    WHERE
      id=?
  `).run(
    cancellationRiderEarnings,
    cancellationRiderEarnings,
    riderWallet.id
  );

  cancelTransactionInsert.run(
    riderWallet.id,
    order.id,
    cancellationRiderEarnings,
    'Cancellation earning',
    cancelReference
  );
}
cancelTransactionUpdate.run(
  cancellationCharge,
  order.rider_id || null,
  cancellationRiderEarnings,
  cancellationLocusEarnings,
  cancelTransaction.customer_payment_status ===
    'paid'
    ? 'paid'
    : 'unpaid',
  order.id
);

        if (
          cancelTransaction.customer_payment_status ===
            'unpaid'
        ) {
          /*
            Pay-on-delivery cancellation charges remain
            unpaid. No wallet adjustment is made.
          */
        }
      });

    try {
      performCancellation();
    } catch (error) {
      if (
        error.message ===
        'CANCELLATION_CONFLICT'
      ) {
        return res.status(409).send(
          page(
            'Cancel Order',
            `
            <div class="card">
              ${alertBox(
                'The order could not be cancelled because its status changed. Please refresh your orders and try again.'
              )}

              <a
                class="btn"
                href="/customer/orders"
              >
                Back to Orders
              </a>
            </div>
            `,
            req
          )
        );
      }

      throw error;
    }

    res.redirect('/customer/orders');
  }
);

