app.post(
  '/business/store/products/:productId/edit',
  requireRole('business'),
  businessProductPhotoUpload.single('product_photo'),
  csrfCheck,
  (req, res) => {

    const businessId =
      req.session.user.id;

    const productId =
      Number(req.params.productId);

    if (
      !Number.isInteger(productId) ||
      productId <= 0
    ) {
      return res.status(400).send(
        'Invalid product.'
      );
    }

    const product = db.prepare(`
      SELECT
        id,
        photo_path
      FROM business_store_products
      WHERE id=?
        AND business_user_id=?
    `).get(
      productId,
      businessId
    );

    if (!product) {
      return res.status(404).send(
        'Product not found.'
      );
    }

    const name =
      String(req.body.name || '')
        .trim()
        .slice(0, 160);

    const description =
      String(req.body.description || '')
        .trim()
        .slice(0, 1000);

    const sku =
      String(req.body.sku || '')
        .trim()
        .slice(0, 80);

    const price =
      Number(req.body.price);

    const stockQuantity =
      Number(req.body.stock_quantity);

    const active =
      req.body.active === '1'
        ? 1
        : 0;

    if (!name) {
      return res.status(400).send(
        'Product name is required.'
      );
    }

    if (
      !Number.isFinite(price) ||
      price < 0
    ) {
      return res.status(400).send(
        'Enter a valid product price.'
      );
    }

    if (
      !Number.isInteger(stockQuantity) ||
      stockQuantity < 0
    ) {
      return res.status(400).send(
        'Enter a valid stock quantity.'
      );
    }

    const newPhoto =
      req.file?.path || product.photo_path;

    db.prepare(`
      UPDATE business_store_products
      SET
        name=?,
        description=?,
        sku=?,
        price=?,
        stock_quantity=?,
        active=?,
        photo_path=?,
        updated_at=CURRENT_TIMESTAMP
      WHERE id=?
        AND business_user_id=?
    `).run(
      name,
      description || null,
      sku || null,
      price,
      stockQuantity,
      active,
      newPhoto || null,
      productId,
      businessId
    );

    res.redirect(
      '/business/store/products'
    );
  }
);
app.post(
  '/business/store/products/:productId/delete',
  requireRole('business'),
  csrfCheck,
  (req, res) => {

    const businessId =
      req.session.user.id;

    const productId =
      Number(req.params.productId);

    if (
      !Number.isInteger(productId) ||
      productId <= 0
    ) {
      return res.status(400).send(
        'Invalid product.'
      );
    }

    const product = db.prepare(`
      SELECT
        id,
        photo_path
      FROM business_store_products
      WHERE id=?
        AND business_user_id=?
    `).get(
      productId,
      businessId
    );

    if (!product) {
      return res.status(404).send(
        'Product not found.'
      );
    }

    db.prepare(`
      DELETE FROM business_store_products
      WHERE id=?
        AND business_user_id=?
    `).run(
      productId,
      businessId
    );

    if (product.photo_path) {
      const photoPath =
        path.resolve(
          product.photo_path
        );

      const uploadRoot =
        path.resolve(
          __dirname,
          'uploads',
          'business-products'
        );

      if (
        photoPath.startsWith(
          uploadRoot + path.sep
        ) &&
        fs.existsSync(photoPath)
      ) {
        try {
          fs.unlinkSync(photoPath);
        } catch (error) {
          console.error(
            'Product photo deletion error:',
            error
          );
        }
      }
    }

    res.redirect(
      '/business/store/products'
    );
  }
);
