app.post(
  '/business/store/profile',
  requireRole('business'),
  businessPhotoUpload.single('business_profile_photo'),
  csrfCheck,
  (req, res) => {

const businessId = req.session.user.id;

const existingBusiness = db.prepare(`
  SELECT
    business_profile_photo_path
  FROM users
  WHERE id=?
    AND role='business'
`).get(businessId);

if (!existingBusiness) {
  if (req.file?.path) {
    try {
      fs.unlinkSync(req.file.path);
    } catch (_) {}
  }

  return res.status(404).send(
    'Business account not found.'
  );
}

const oldBusinessPhoto =
  existingBusiness.business_profile_photo_path;

const newBusinessPhoto =
  req.file?.path || oldBusinessPhoto;

const businessName =
      String(req.body.business_name || '')
        .trim()
        .slice(0, 120);

    const registrationNumber =
      String(
        req.body.business_registration_number || ''
      )
        .trim()
        .slice(0, 80);

    const businessAddress =
      String(req.body.business_address || '')
        .trim()
        .slice(0, 200);

    if (!businessName) {
      return res.status(400).send(
        'Store name is required.'
      );
    }

db.prepare(`
  UPDATE users
  SET
    business_name=?,
    business_registration_number=?,
    business_address=?,
    business_profile_photo_path=?
  WHERE id=?
    AND role='business'
`).run(
  businessName,
  registrationNumber || null,
  businessAddress || null,
  newBusinessPhoto,
  businessId
);
if (
  req.file?.path &&
  oldBusinessPhoto &&
  oldBusinessPhoto !== newBusinessPhoto
) {
  const businessesRoot = path.resolve(
    __dirname,
    'uploads',
    'businesses'
  );

  const oldBusinessPhotoPath =
    path.resolve(oldBusinessPhoto);

  if (
    oldBusinessPhotoPath.startsWith(
      businessesRoot + path.sep
    ) &&
    fs.existsSync(oldBusinessPhotoPath)
  ) {
    try {
      fs.unlinkSync(oldBusinessPhotoPath);
    } catch (err) {
      console.error(
        'Locus: failed to remove old business photo:',
        err.message
      );
    }
  }
}
    res.redirect('/business/store/profile');

  }
);
app.get(
  '/business/store/preview-photo',
  requireRole('business'),
  (req, res) => {

    const businessId =
      req.session.user.id;

    const business = db.prepare(`
      SELECT
        business_profile_photo_path
      FROM users
      WHERE id=?
        AND role='business'
        AND active=1
    `).get(businessId);

    if (
      !business ||
      !business.business_profile_photo_path
    ) {
      return res.status(404).end();
    }

    const businessesRoot = path.resolve(
      __dirname,
      'uploads',
      'businesses'
    );

    const photoPath = path.resolve(
      business.business_profile_photo_path
    );

    if (
      !photoPath.startsWith(
        businessesRoot + path.sep
      )
    ) {
      return res.status(403).end();
    }

    if (!fs.existsSync(photoPath)) {
      return res.status(404).end();
    }

    const fileBuffer =
      fs.readFileSync(photoPath);

    let contentType =
      'application/octet-stream';

    if (
      fileBuffer.length >= 3 &&
      fileBuffer[0] === 0xFF &&
      fileBuffer[1] === 0xD8 &&
      fileBuffer[2] === 0xFF
    ) {
      contentType = 'image/jpeg';
    } else if (
      fileBuffer.length >= 8 &&
      fileBuffer[0] === 0x89 &&
      fileBuffer[1] === 0x50 &&
      fileBuffer[2] === 0x4E &&
      fileBuffer[3] === 0x47 &&
      fileBuffer[4] === 0x0D &&
      fileBuffer[5] === 0x0A &&
      fileBuffer[6] === 0x1A &&
      fileBuffer[7] === 0x0A
    ) {
      contentType = 'image/png';
    } else if (
      fileBuffer.length >= 12 &&
      fileBuffer.toString(
        'ascii',
        0,
        4
      ) === 'RIFF' &&
      fileBuffer.toString(
        'ascii',
        8,
        12
      ) === 'WEBP'
    ) {
      contentType = 'image/webp';
    } else {
      return res.status(415).end();
    }

    res.type(contentType);
    res.send(fileBuffer);
  }
);
app.get(
  '/business/store/preview/product/:productId',
  (req, res) => {
    const productId =
      Number(req.params.productId);

    if (
      !Number.isInteger(productId) ||
      productId <= 0
    ) {
      return res.status(400).send(
        'Invalid product.'
      );
    }

    const product = db.prepare(`
      SELECT
        p.id,
        p.name,
        p.description,
        p.price,
        p.stock_quantity,
        p.photo_path,
        p.business_user_id,
        u.business_name,
        u.business_address
      FROM business_store_products p
      INNER JOIN users u
        ON u.id = p.business_user_id
      WHERE p.id=?
        AND p.active=1
        AND u.role='business'
        AND u.active=1
    `).get(productId);

    if (!product) {
      return res.status(404).send(
        'Product not found.'
      );
    }

    const photoPath =
      product.photo_path
        ? path.resolve(product.photo_path)
        : null;

    const uploadRoot =
      path.resolve(
        __dirname,
        'uploads',
        'business-products'
      );

    let photoHtml = `
      <div
        style="
          width:100%;
          height:420px;
          background:#f8fafc;
          display:flex;
          align-items:center;
          justify-content:center;
          border-radius:18px;
          overflow:hidden;
          border:1px solid #e2e8f0;
        "
      >
        <div style="font-size:80px;">
          &#128444;
        </div>
      </div>
    `;

    if (
      photoPath &&
      photoPath !== uploadRoot &&
      photoPath.startsWith(
        uploadRoot + path.sep
      ) &&
      fs.existsSync(photoPath)
    ) {
      photoHtml = `
        <div
          style="
            width:100%;
            height:420px;
            background:#ffffff;
            display:flex;
            align-items:center;
            justify-content:center;
            border-radius:18px;
            overflow:hidden;
            border:1px solid #e2e8f0;
          "
        >
          <img
            src="/business/store/preview-product-photo/${product.id}"
            alt="${String(product.name || '')
              .replace(/"/g, '&quot;')}"
            style="
              width:100%;
              height:100%;
              object-fit:contain;
              display:block;
            "
          >
        </div>
      `;
    }

    const stockText =
      Number(product.stock_quantity) > 0
        ? `${product.stock_quantity} available`
        : 'Out of stock';

    const addButton =
      Number(product.stock_quantity) > 0
        ? `
          <button
            type="button"
            id="addProductToCartButton"
            style="
              width:100%;
              padding:14px;
              border:none;
              border-radius:12px;
              background:#0B294D;
              color:#ffffff;
              font-size:16px;
              font-weight:700;
              cursor:pointer;
            "
          >
            Add to Cart
          </button>
        `
        : `
          <button
            type="button"
            disabled
            style="
              width:100%;
              padding:14px;
              border:none;
              border-radius:12px;
              background:#cbd5e1;
              color:#475569;
              font-size:16px;
              font-weight:700;
            "
          >
            Out of Stock
          </button>
        `;

    const html = `
      <div
        style="
          max-width:760px;
          margin:0 auto;
          padding:24px;
        "
      >

        <div
          style="
            display:flex;
            align-items:center;
            justify-content:space-between;
            margin-bottom:20px;
          "
        >
          <a
            href="/business/store/preview"
            style="
              text-decoration:none;
              color:#0B294D;
              font-weight:700;
            "
          >
            ? Back to Store
          </a>

          <div
            style="
              font-size:20px;
              font-weight:800;
              color:#0B294D;
            "
          >
            Locus Store
          </div>
        </div>

        ${photoHtml}

        <div
          style="
            margin-top:22px;
          "
        >

          <div
            style="
              font-size:13px;
              color:#64748b;
              margin-bottom:6px;
            "
          >
            ${String(product.business_name || '')}
          </div>

          <h1
            style="
              margin:0 0 10px;
              color:#0B294D;
              font-size:28px;
            "
          >
            ${String(product.name || '')}
          </h1>

          <div
            style="
              font-size:24px;
              font-weight:800;
              color:#D4AF37;
              margin-bottom:12px;
            "
          >
            KSh ${Number(product.price || 0).toFixed(2)}
          </div>

          <div
            style="
              color:#475569;
              margin-bottom:18px;
            "
          >
            ${String(product.description || 'No description available.')}
          </div>

          <div
            style="
              padding:12px;
              border-radius:10px;
              background:#f8fafc;
              margin-bottom:18px;
              color:#334155;
            "
          >
            ${stockText}
          </div>

          ${addButton}

        </div>

      </div>
    `;

    const productDetailsScript = `
      <script>
        (() => {

          const addButton =
            document.getElementById(
              'addProductToCartButton'
            );

          if (!addButton) {
            return;
          }

          addButton.addEventListener(
            'click',
            () => {

              const productId =
                ${Number(product.id)};

              const productName =
                ${JSON.stringify(
                  String(product.name || 'Product')
                )};

              const stock =
                ${Number(product.stock_quantity || 0)};

              if (
                !Number.isInteger(productId) ||
                productId <= 0 ||
                stock <= 0
              ) {
                return;
              }

              let cart = [];

              try {
                const savedCart =
                  sessionStorage.getItem(
                    'locusBusinessStoreCart'
                  );

                if (savedCart) {
                  const parsedCart =
                    JSON.parse(savedCart);

                  if (Array.isArray(parsedCart)) {
                    cart = parsedCart;
                  }
                }
              } catch (error) {
                cart = [];
              }

              const existing =
                cart.find(
                  item =>
                    Number(item.id) === productId
                );

              const currentQuantity =
                existing
                  ? Number(existing.quantity || 1)
                  : 0;

              const remainingStock =
                Math.max(
                  0,
                  stock - currentQuantity
                );

              if (remainingStock <= 0) {
                alert(
                  'Only ' +
                  stock +
                  ' available for ' +
                  productName +
                  '.'
                );
                return;
              }

              const quantityInput =
                prompt(
                  'How many ' +
                  productName +
                  ' would you like?\\\\n\\\\nAvailable: ' +
                  remainingStock,
                  '1'
                );

              if (quantityInput === null) {
                return;
              }

              const quantity =
                Number(quantityInput);

              if (
                !Number.isInteger(quantity) ||
                quantity <= 0
              ) {
                alert(
                  'Please enter a valid quantity.'
                );
                return;
              }

              if (quantity > remainingStock) {
                alert(
                  'Only ' +
                  remainingStock +
                  ' available.'
                );
                return;
              }

              if (existing) {
                existing.quantity =
                  Number(existing.quantity || 1) +
                  quantity;
              } else {
                cart.push({
                  id: productId,
                  name: productName,
                  quantity: quantity,
                  businessId: Number(product.business_user_id)
                });

              sessionStorage.setItem(
                'locusBusinessStoreCart',
                JSON.stringify(cart)
              );

              addButton.textContent =
                '? Added to Cart';

              setTimeout(() => {
                addButton.textContent =
                  'Add to Cart';
              }, 1200);

            }
          );

        })();
      </script>
    `;

    return res.send(
      page(
        'Product Details',
        html + productDetailsScript,
        req
      )
    );
  }
);

