app.post(
  '/business/notifications/read',
  requireRole('business'),
  (req, res) => {

    const businessId =
      req.session.user.id;

    const notificationId =
      Number(req.body.id);

    if (
      !Number.isInteger(notificationId) ||
      notificationId <= 0
    ) {
      return res.status(400).send(
        'Invalid notification.'
      );
    }

    db.prepare(`
      UPDATE business_notifications
      SET read_at=CURRENT_TIMESTAMP
      WHERE
        id=?
        AND business_user_id=?
        AND active=1
    `).run(
      notificationId,
      businessId
    );

    return res.redirect(
      '/business/notifications'
    );
  }
);
app.get(
  '/business/notifications',
  requireRole('business'),
  (req, res) => {
    const businessId = req.session.user.id;

    const notifications = db.prepare(`
      SELECT
        n.id,
        n.title,
        n.message,
        n.notification_type,
        n.order_id,
        n.read_at,
        n.created_at,
        o.order_number
      FROM business_notifications n
      LEFT JOIN orders o
        ON o.id=n.order_id
      WHERE
        n.business_user_id=?
        AND n.active=1
      ORDER BY n.id DESC
    `).all(businessId);

    const notificationContent =
      notifications.length === 0
        ? `
          <section class="card">
            <div
              style="
                text-align:center;
                padding:30px 10px;
              "
            >
              <div
                style="
                  font-size:38px;
                  margin-bottom:10px;
                "
              >
                Store
              </div>

              <h2 style="margin:0 0 6px;">
                No notifications
              </h2>

              <p class="muted">
                You don't have any notifications yet.
              </p>
            </div>
          </section>
        `
        : `
          <div
            style="
              display:grid;
              gap:12px;
            "
          >
            ${notifications.map(notification => `
              <section
                class="card"
                style="
                  border:1px solid ${
                    notification.read_at
                      ? '#e5e7eb'
                      : '#D4AF37'
                  };
                "
              >

                <div
                  style="
                    display:flex;
                    align-items:flex-start;
                    justify-content:space-between;
                    gap:14px;
                  "
                >

                  <div style="flex:1;">

                    <h3
                      style="
                        margin:0 0 6px;
                      "
                    >
                      ${escapeHtml(
                        notification.title
                      )}
                    </h3>

                    <p
                      style="
                        margin:0 0 8px;
                      "
                    >
                      ${escapeHtml(
                        notification.message
                      )}
                    </p>

                    ${
                      notification.order_number
                        ? `
                          <div
                            class="muted"
                            style="font-size:13px;"
                          >
                            Order:
                            <strong>
                              ${escapeHtml(
                                notification.order_number
                              )}
                            </strong>
                          </div>
                        `
                        : ''
                    }

                    <div
                      class="muted"
                      style="
                        font-size:12px;
                        margin-top:7px;
                      "
                    >
                      ${escapeHtml(
                        notification.created_at
                      )}
                    </div>

                  </div>

                  ${
                    notification.read_at
                      ? `
                        <span
                          class="muted"
                          style="
                            font-size:12px;
                            white-space:nowrap;
                          "
                        >
                          &#10003; Read
                        </span>
                      `
                      : `
                        <form
                          method="post"
                          action="/business/notifications/read"
                          style="margin:0;"
                        >

                          <input
                            type="hidden"
                            name="_csrf"
                            value="${csrf(req)}"
                          >

                          <input
                            type="hidden"
                            name="id"
                            value="${notification.id}"
                          >

                          <button
                            type="submit"
                            class="btn"
                            style="
                              padding:7px 10px;
                              font-size:12px;
                              white-space:nowrap;
                            "
                          >
                            Mark as Read
                          </button>

                        </form>
                      `
                  }

                </div>

              </section>
            `).join('')}
          </div>
        `;

    return res.send(
      page(
        'Business Notifications',
        `
        <main
          style="
            max-width:900px;
            margin:0 auto;
            padding:20px;
          "
        >

          <div
            style="
              display:flex;
              align-items:center;
              justify-content:space-between;
              gap:12px;
              margin-bottom:20px;
            "
          >

            <div>
              <h1 style="margin-bottom:4px;">
                Notifications
              </h1>

              <p class="muted">
                Updates about your Locus Business account and orders.
              </p>
            </div>

            <a
              href="/business"
              class="btn"
            >
              &#8592; Back
            </a>

          </div>

          ${notificationContent}

        </main>
        `,
        req
      )
    );
  }
);
