app.post(
  '/business/profile/edit',
  requireRole('business'),
  csrfCheck,
  (req, res) => {
    const businessId = req.session.user.id;

    const businessName =
      String(req.body.business_name || '').trim();

    const registrationNumber =
      String(
        req.body.business_registration_number || ''
      ).trim();

    const businessAddress =
      String(req.body.business_address || '').trim();

    const email =
      String(req.body.email || '').trim();

    const phone =
      String(req.body.phone || '').trim();

    if (!businessName) {
      return res.status(400).send(
        'Business name is required.'
      );
    }

    if (!businessAddress) {
      return res.status(400).send(
        'Business address is required.'
      );
    }

    if (!email) {
      return res.status(400).send(
        'Email is required.'
      );
    }

    if (!phone) {
      return res.status(400).send(
        'Phone is required.'
      );
    }

    const existingEmail = db.prepare(`
      SELECT id
      FROM users
      WHERE email=?
        AND id<>?
      LIMIT 1
    `).get(email, businessId);

    if (existingEmail) {
      return res.status(400).send(
        'That email address is already in use.'
      );
    }

    db.prepare(`
      UPDATE users
      SET
        business_name=?,
        business_registration_number=?,
        business_address=?,
        email=?,
        phone=?
      WHERE id=?
        AND role='business'
    `).run(
      businessName,
      registrationNumber || null,
      businessAddress,
      email,
      phone,
      businessId
    );

    return res.redirect('/business/profile');
  }
);


