app.post(
  '/business/payment/:id/reference',
  requireRole('business'),
  csrfCheck,
  (req, res) => {
    const requestId = Number(req.params.id);
    const reference = String(req.body.payment_reference || '').trim();

    if (!Number.isInteger(requestId) || requestId <= 0) {
      return res.status(400).send('Invalid payment request.');
    }

    if (!reference || reference.length > 100) {
      return res.status(400).send(
        page('Invalid Payment Reference',
          '<div class="card narrow"><h1>Invalid Payment Reference</h1><p>Enter a valid payment reference of up to 100 characters.</p><a class="btn" href="/business">Back to Dashboard</a></div>',
          req)
      );
    }

    const paymentRequest = db.prepare(`
      SELECT id, status
      FROM business_payment_requests
      WHERE id = ? AND business_user_id = ?
    `).get(requestId, req.session.user.id);

    if (!paymentRequest) {
      return res.status(404).send('Payment request not found.');
    }

    if (paymentRequest.status !== 'pending') {
      return res.status(409).send(
        page('Request Already Processed',
          '<div class="card narrow"><h1>Request Already Processed</h1><p>This payment request is no longer awaiting reference submission.</p><a class="btn" href="/business">Back to Dashboard</a></div>',
          req)
      );
    }

    db.prepare(`
      UPDATE business_payment_requests
      SET payment_reference = ?,
          updated_at = CURRENT_TIMESTAMP
      WHERE id = ?
        AND business_user_id = ?
        AND status = 'pending'
    `).run(reference, requestId, req.session.user.id);

    return res.redirect(`/business/payment/${requestId}`);
  }
);
