app.post(
  '/customer/wallet/topup',
  csrfCheck,
  requireRole('customer'),
  (req, res) => {

    const errandServiceFee =
      Number(getLocusSetting('errand_service_fee', 500));

    const customerId = req.session.user.id;
    const amount = Number(req.body.amount);

    if (
      !Number.isFinite(amount) ||
      amount <= 0 ||
      amount > 100000
    ) {
      return res.status(400).send(
        page(
          'Invalid top-up',
          `
          <div class="card narrow">
            <h1>Invalid Amount</h1>

            <p class="muted">
              Enter a valid sandbox amount between
              KSh 1 and KSh 100,000.
            </p>

            <a
              class="btn"
              href="/customer/wallet"
            >
              Back to Wallet
            </a>
          </div>
          `,
          req
        )
      );
    }

    const wallet = db.prepare(`
      SELECT id
      FROM wallets
      WHERE user_id=?
    `).get(customerId);

    if (!wallet) {
      return res.status(500).send(
        page(
          'Wallet unavailable',
          `
          <div class="card narrow">
            <h1>Wallet Unavailable</h1>

            <p class="muted">
              Your customer wallet could not be found.
            </p>

            <a
              class="btn"
              href="/customer"
            >
              Back to Dashboard
            </a>
          </div>
          `,
          req
        )
      );
    }

    const reference =
      'SANDBOX-' +
      Date.now().toString(36).toUpperCase();

    const topUp = db.transaction(() => {

      db.prepare(`
        UPDATE wallets
        SET
          balance = balance + ?,
          updated_at = CURRENT_TIMESTAMP
        WHERE id=?
      `).run(
        amount,
        wallet.id
      );

      db.prepare(`
        INSERT INTO wallet_transactions (
          wallet_id,
          type,
          amount,
          description,
          reference
        )
        VALUES (
          ?,
          'adjustment',
          ?,
          ?,
          ?
        )
      `).run(
        wallet.id,
        amount,
        'Sandbox wallet top-up',
        reference
      );

    });

    topUp();

    res.redirect('/customer/wallet');

  }
);
function distanceInMeters(lat1, lon1, lat2, lon2) {
  const R = 6371000;

  const toRadians = value =>
    value * Math.PI / 180;

  const dLat =
    toRadians(lat2 - lat1);

  const dLon =
    toRadians(lon2 - lon1);

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRadians(lat1)) *
    Math.cos(toRadians(lat2)) *
    Math.sin(dLon / 2) ** 2;

  const c =
    2 * Math.atan2(
      Math.sqrt(a),
      Math.sqrt(1 - a)
    );

  return R * c;
}

function riderWithin100Meters(
  riderId,
  latitude,
  longitude
) {
  const rider = db.prepare(`
    SELECT
      current_latitude,
      current_longitude,
      last_location_update
    FROM users
    WHERE
      id=?
      AND role='rider'
  `).get(riderId);

  if (
    !rider ||
    !Number.isFinite(
      Number(rider.current_latitude)
    ) ||
    !Number.isFinite(
      Number(rider.current_longitude)
    )
  ) {
    return {
      ok: false,
      distance: null,
      error: 'Rider GPS location is not available.'
    };
  }

  const distance =
    distanceInMeters(
      Number(rider.current_latitude),
      Number(rider.current_longitude),
      Number(latitude),
      Number(longitude)
    );

  return {
    ok: distance <= 100,
    distance
  };
}
