app.post(
  '/rider/location',
  csrfCheck,
  requireRole('rider'),
  (req, res) => {

    const latitude = Number(req.body.latitude);
    const longitude = Number(req.body.longitude);

    if (
      !Number.isFinite(latitude) ||
      !Number.isFinite(longitude) ||
      latitude < -90 ||
      latitude > 90 ||
      longitude < -180 ||
      longitude > 180
    ) {
      return res.status(400).json({
        ok: false,
        error: 'Invalid location.'
      });
    }

    db.prepare(`
      UPDATE users
      SET
        current_latitude=?,
        current_longitude=?,
        last_location_update=CURRENT_TIMESTAMP
      WHERE
        id=?
        AND role='rider'
    `).run(
      latitude,
      longitude,
      req.session.user.id
    );

    res.json({
      ok: true
    });
  }
);
/* =========================================================
   GPS DISTANCE CHECK
========================================================= */

function distanceInMeters(
  lat1,
  lon1,
  lat2,
  lon2
) {
  const R = 6371000;

  const toRadians = value =>
    value * Math.PI / 180;

  const dLat =
    toRadians(lat2 - lat1);

  const dLon =
    toRadians(lon2 - lon1);

  const a =
    Math.sin(dLat / 2) *
    Math.sin(dLat / 2) +
    Math.cos(toRadians(lat1)) *
    Math.cos(toRadians(lat2)) *
    Math.sin(dLon / 2) *
    Math.sin(dLon / 2);

  const c =
    2 *
    Math.atan2(
      Math.sqrt(a),
      Math.sqrt(1 - a)
    );

  return R * c;
}

function riderWithin100Meters(
  rider,
  latitude,
  longitude
) {
  if (
    !rider ||
    !Number.isFinite(Number(rider.current_latitude)) ||
    !Number.isFinite(Number(rider.current_longitude)) ||
    !Number.isFinite(Number(latitude)) ||
    !Number.isFinite(Number(longitude))
  ) {
    return false;
  }

  return (
    distanceInMeters(
      Number(rider.current_latitude),
      Number(rider.current_longitude),
      Number(latitude),
      Number(longitude)
    ) <= 100
  );
}
