app.post(
  '/rider/order/:id/reject',
  csrfCheck,
  requireRole('rider'),
  (req, res) => {

    const id =
      Number(req.params.id);

    const riderId =
      req.session.user.id;

    const dispatch = db.prepare(`
      SELECT
        id,
        order_id,
        rider_id,
        status
      FROM order_dispatches
      WHERE
        order_id=?
        AND rider_id=?
        AND status='offered'
      ORDER BY id DESC
      LIMIT 1
    `).get(
      id,
      riderId
    );

    if (!dispatch) {
      return res.redirect('/rider');
    }

    /*
      Record the rejection.
    */

    db.prepare(`
      UPDATE order_dispatches
      SET
        status='rejected',
        responded_at=CURRENT_TIMESTAMP
      WHERE
        id=?
    `).run(
      dispatch.id
    );

    /*
      Reduce rider score by 0.5 points.
      Never allow the score to go below 0.
    */

    db.prepare(`
      UPDATE users
      SET
        score = MAX(0, COALESCE(score, 100) - 0.5)
      WHERE
        id=?
        AND role='rider'
    `).run(
      riderId
    );

    /*
      Remove this rider from the order.
      The order becomes available for
      another rider.
    */

    db.prepare(`
      UPDATE orders
      SET
        rider_id=NULL,
        updated_at=CURRENT_TIMESTAMP
      WHERE
        id=?
        AND rider_id=?
        AND status='pending'
    `).run(
      id,
      riderId
    );

    /*
      Record order history.
    */

    db.prepare(`
      INSERT INTO order_events(
        order_id,
        user_id,
        event,
        notes
      )
      VALUES(
        ?,
        ?,
        'rejected',
        'Rider rejected the dispatched order. Rider score reduced by 0.5 points.'
      )
    `).run(
      id,
      riderId
    );

    /*
      Immediately look for another rider.
    */

    dispatchOrder(id);

    res.redirect('/rider');
  }
);
