/* =========================================================
   RIDER ON THE WAY
========================================================= */
app.post(
  '/rider/order/:id/on-the-way',
  csrfCheck,
  requireRole('rider'),
  requireRiderOnline,
  (req, res) => {

    const id =
      Number(req.params.id);

    const riderId =
      req.session.user.id;

    const order = db.prepare(`
      SELECT
        id,
        rider_id,
        status,
        business_trip_id,
        business_trip_sequence
      FROM orders
      WHERE
        id=?
        AND rider_id=?
      LIMIT 1
    `).get(
      id,
      riderId
    );

    if (!order) {
      return res.redirect('/rider');
    }

    const isBusinessNextStop =
      Boolean(order.business_trip_id) &&
      Number(order.business_trip_sequence) > 1;

    let previousBusinessStopDelivered = true;

    if (isBusinessNextStop) {
      const previousStop = db.prepare(`SELECT status FROM orders WHERE business_trip_id=? AND rider_id=? AND business_trip_sequence=? LIMIT 1`).get(
        order.business_trip_id,
        riderId,
        Number(order.business_trip_sequence) - 1
      );

      previousBusinessStopDelivered =
        Boolean(previousStop) &&
        previousStop.status === 'delivered';
    }

    let result;

    if (isBusinessNextStop) {

      if (!previousBusinessStopDelivered) {
        return res.redirect('/rider');
      }

      /*
        Business multi-stop flow:

        Stop 1:
          A -> B
          uses normal pickup flow.

        Stops 2-5:
          A is still the stored business pickup
          for billing purposes, but the rider has
          already completed the previous destination.

        Therefore the rider moves directly toward
        this stop's drop-off.

        Physical rider flow:
          A -> B -> C -> D -> E -> F
      */

      result = db.prepare(`
        UPDATE orders
        SET
          status='on_the_way',
          updated_at=CURRENT_TIMESTAMP
        WHERE
          id=?
          AND rider_id=?
          AND status='accepted'
          AND business_trip_id IS NOT NULL
          AND business_trip_sequence > 1
      `).run(
        id,
        riderId
      );

      if (result.changes === 1) {

        db.prepare(`
          INSERT INTO order_events(
            order_id,
            user_id,
            event,
            notes
          )
          VALUES(
            ?,
            ?,
            'on_the_way',
            'Rider started the next business trip stop without returning to the common pickup.'
          )
        `).run(
          id,
          riderId
        );
      }

    } else {

      /*
        Normal orders and business trip stop 1
        retain the existing pickup workflow.
      */

      result = db.prepare(`
        UPDATE orders
        SET
          status='on_the_way',
          updated_at=CURRENT_TIMESTAMP
        WHERE
          id=?
          AND rider_id=?
          AND status='picked_up'
      `).run(
        id,
        riderId
      );

      if (result.changes === 1) {

        db.prepare(`
          INSERT INTO order_events(
            order_id,
            user_id,
            event,
            notes
          )
          VALUES(
            ?,
            ?,
            'on_the_way',
            'Rider started the delivery after pickup.'
          )
        `).run(
          id,
          riderId
        );
      }
    }

    res.redirect('/rider');
  }
);
/* =========================================================
   RIDER ARRIVED AT DROP-OFF
========================================================= */

app.post(
  '/rider/order/:id/arrived-at-dropoff',
  csrfCheck,
  requireRole('rider'),
  requireRiderOnline,
  (req, res) => {

    const id =
      Number(req.params.id);

    const riderId =
      req.session.user.id;

    const order = db.prepare(`
      SELECT
        id,
        rider_id,
        status,
        dropoff_latitude,
        dropoff_longitude
      FROM orders
      WHERE
        id=?
        AND rider_id=?
    `).get(
      id,
      riderId
    );

    if (!order) {
      return res.redirect('/rider');
    }

    if (order.status !== 'on_the_way') {
      return res.redirect('/rider');
    }

    const rider = db.prepare(`
      SELECT
        current_latitude,
        current_longitude,
        last_location_update
      FROM users
      WHERE
        id=?
        AND role='rider'
    `).get(
      riderId
    );

    const geofence =
      riderWithin100Meters(
        rider,
        order.dropoff_latitude,
        order.dropoff_longitude
      );

    if (!geofence) {

      return res.status(403).send(
        page(
          'Drop-off geofence',
          `
          <div class="card">

            <h2>Too far from drop-off</h2>

            <p>
              You must be within
              <strong>100 metres</strong>
              of the drop-off location before
              confirming arrival.
            </p>

            <p class="muted">
              Please move closer to the drop-off
              point and update your GPS location.
            </p>

            <a
              class="btn"
              href="/rider"
            >
              Back to Rider Dashboard
            </a>

          </div>
          `,
          req
        )
      );
    }

    db.prepare(`
      UPDATE orders
      SET
        status='arrived_at_dropoff',
        updated_at=CURRENT_TIMESTAMP
      WHERE
        id=?
        AND rider_id=?
        AND status='on_the_way'
    `).run(
      id,
      riderId
    );

    db.prepare(`
      INSERT INTO order_events(
        order_id,
        user_id,
        event,
        notes
      )
      VALUES(
        ?,
        ?,
        'arrived_at_dropoff',
        'Rider confirmed arrival at drop-off within the 100m geofence.'
      )
    `).run(
      id,
      riderId
    );

    res.redirect('/rider');
  }
);
