app.post(
  '/rider/order/:id/collect-payment',
  csrfCheck,
  requireRole('rider'),
  requireRiderOnline,
  (req, res) => {

    const id =
      Number(req.params.id);

    const riderId =
      req.session.user.id;

    const order = db.prepare(`
      SELECT
        o.id,
        o.order_number,
        o.service,
        o.amount,
        o.payment_method,
        o.status,
        o.customer_id,
        o.rider_earnings,
        o.dropoff
      FROM orders o
      WHERE
        o.id=?
        AND o.rider_id=?
    `).get(
      id,
      riderId
    );

    if (!order) {
      return res.status(404).send(
        page(
          'Payment',
          `
          <div class="card">
            ${alertBox('Order not found.')}
            <a class="btn" href="/rider">
              Back to Rider Dashboard
            </a>
          </div>
          `,
          req
        )
      );
    }

    if (order.status !== 'arrived_at_dropoff') {
      return res.status(400).send(
        page(
          'Payment',
          `
          <div class="card">
            ${alertBox(
            'Payment can only be collected after arriving at the drop-off.'
          )}
            <a class="btn" href="/rider">
              Back to Rider Dashboard
            </a>
          </div>
          `,
          req
        )
      );
    }

    if (order.payment_method !== 'pay_on_delivery') {
      return res.status(400).send(
        page(
          'Payment',
          `
          <div class="card">
            ${alertBox(
            'This order does not require payment collection.'
          )}
            <a class="btn" href="/rider">
              Back to Rider Dashboard
            </a>
          </div>
          `,
          req
        )
      );
    }

    const financial = db.prepare(`
      SELECT
        customer_payment_status,
        rider_debt_status
      FROM financial_transactions
      WHERE order_id=?
    `).get(
      order.id
    );
if (
  financial &&
  financial.customer_payment_status === 'paid'
) {
  return res.redirect('/rider');
}
    return res.send(
      page(
        'Collect Payment',
        `
        <div class="card narrow">

          <div class="pill">
            SANDBOX PAYMENT COLLECTION
          </div>

          <h1>
            Collect Customer Payment
          </h1>

          <p class="muted">
            This is a Locus sandbox payment confirmation.
            No real M-Pesa money will be moved.
          </p>

          <div class="card">

            <h2>
              Payment Summary
            </h2>

            <p>
              <strong>Order:</strong>
              ${e(order.order_number || 'LOC#' + order.id)}
            </p>

            <p>
              <strong>Service:</strong>
              ${e(order.service)}
            </p>

            <p>
              <strong>Drop-off:</strong>
              ${e(order.dropoff)}
            </p>

            <p>
              <strong>Customer amount:</strong>
              KSh ${Number(order.amount || 0).toFixed(2)}
            </p>

          </div>

          <div class="card">

            <h2>
              Customer Payment
            </h2>

            <p>
              Confirm that the customer has paid
              the full amount for this request.
            </p>

            <p class="muted">
              In the live Locus system, this step can
              be connected to the approved payment
              method or Soundbox integration.
            </p>

          </div>

          <form
            method="post"
            action="/rider/order/${order.id}/confirm-payment"
          >

            <input
              type="hidden"
              name="_csrf"
              value="${csrf(req)}"
            >

            <button
              type="submit"
              class="btn full"
            >
              Confirm Customer Payment
            </button>

          </form>

          <div style="margin-top:10px;">

            <a
              class="btn full"
              href="/rider"
            >
              Cancel
            </a>

          </div>

        </div>
        `,
        req
      )
    );
  }
);

