app.post(
  '/rider/order/:id/confirm-payment',
  csrfCheck,
  requireRole('rider'),
  requireRiderOnline,
  (req, res) => {

    const id =
      Number(req.params.id);

    const riderId =
      req.session.user.id;

    const order = db.prepare(`
SELECT
  id,
  rider_id,
  status,
  payment_method,
  rider_earnings,
  amount,
  delivery_otp_verified
FROM orders
      WHERE
        id=?
        AND rider_id=?
    `).get(
      id,
      riderId
    );

    if (!order) {
      return res.status(404).send(
        page(
          'Payment',
          `
          <div class="card">
            ${alertBox('Order not found.')}
            <a class="btn" href="/rider">
              Back to Rider Dashboard
            </a>
          </div>
          `,
          req
        )
      );
    }

    if (
      order.status !== 'arrived_at_dropoff' ||
      order.payment_method !== 'pay_on_delivery'
    ) {
      return res.status(400).send(
        page(
          'Payment',
          `
          <div class="card">
            ${alertBox(
            'This payment cannot be confirmed for the current order state.'
          )}
            <a class="btn" href="/rider">
              Back to Rider Dashboard
            </a>
          </div>
          `,
          req
        )
      );
    }
if (
  Number(order.delivery_otp_verified || 0) !== 1
) {
  return res.status(400).send(
    page(
      'Delivery OTP Required',
      `
      <div class="card">

        <h2>
          Delivery OTP Required
        </h2>

        <p>
          The customer's delivery OTP must be
          verified before payment can be confirmed.
        </p>

        ${alertBox(
          'Please verify the customer OTP first.'
        )}

        <a
          class="btn full"
          href="/rider"
        >
          Back to Rider Dashboard
        </a>

      </div>
      `,
      req
    )
  );
}
    const financial =
      db.prepare(`
        SELECT
          id,
          customer_payment_status
        FROM financial_transactions
        WHERE order_id=?
      `).get(
        order.id
      );

    if (!financial) {
      return res.status(400).send(
        page(
          'Payment',
          `
          <div class="card">
            ${alertBox(
            'Financial transaction for this order was not found.'
          )}
            <a class="btn" href="/rider">
              Back to Rider Dashboard
            </a>
          </div>
          `,
          req
        )
      );
    }

    const locusEarnings =
      Math.max(
        0,
        Number(order.amount || 0) -
        Number(order.rider_earnings || 0)
      );

    db.transaction(() => {

      db.prepare(`
        UPDATE financial_transactions
        SET
          customer_payment_status='paid',
          rider_debt_status=?,
          updated_at=CURRENT_TIMESTAMP
        WHERE
          order_id=?
      `).run(
        locusEarnings > 0
          ? 'unpaid'
          : 'none',
        order.id
      );

      db.prepare(`
        INSERT INTO order_events (
          order_id,
          user_id,
          event,
          notes
        )
        VALUES (
          ?,
          ?,
          'payment_collected',
          ?
        )
      `).run(
        order.id,
        riderId,
        'Customer payment confirmed by rider in Locus sandbox.'
      );

    })();

   /*
  Payment is confirmed, but delivery is NOT completed yet.

  The rider must return to the dashboard and enter
  the customer's delivery OTP before the order can
  become delivered.
*/

res.redirect('/rider');
  }
);
/* =========================================================
   RIDER VERIFY DELIVERY OTP
========================================================= */

app.post(
  '/rider/order/:id/verify-otp',
  csrfCheck,
  requireRole('rider'),
  requireRiderOnline,
  (req, res) => {

    const id =
      Number(req.params.id);

    const riderId =
      req.session.user.id;

    const otp =
      String(
        req.body.delivery_otp || ''
      ).trim();

    const order = db.prepare(`
      SELECT
        id,
        rider_id,
        status,
        delivery_otp,
        delivery_otp_verified
      FROM orders
      WHERE
        id=?
        AND rider_id=?
    `).get(
      id,
      riderId
    );

    if (!order) {
      return res.redirect('/rider');
    }

    if (
      order.status !== 'arrived_at_dropoff'
    ) {
      return res.status(400).send(
        page(
          'Delivery OTP',
          `
          <div class="card">

            <h2>
              Delivery OTP
            </h2>

            ${alertBox(
              'OTP can only be verified after arriving at the drop-off.'
            )}

            <a
              class="btn full"
              href="/rider"
            >
              Back to Rider Dashboard
            </a>

          </div>
          `,
          req
        )
      );
    }

    if (
      !order.delivery_otp ||
      otp !== String(order.delivery_otp)
    ) {

      return res.status(400).send(
        page(
          'Invalid Delivery OTP',
          `
          <div class="card">

            <h2>
              Invalid Delivery OTP
            </h2>

            ${alertBox(
              order.delivery_otp
                ? 'The OTP entered is incorrect. The order has NOT been completed.'
                : 'This order does not have a valid delivery OTP.'
            )}

            <p class="muted">
              Ask the customer for the correct delivery OTP
              and try again.
            </p>

            <a
              class="btn full"
              href="/rider"
            >
              Back to Rider Dashboard
            </a>

          </div>
          `,
          req
        )
      );
    }

    db.transaction(() => {

      db.prepare(`
        UPDATE orders
        SET
          delivery_otp_verified=1,
          delivery_otp_verified_at=CURRENT_TIMESTAMP,
          updated_at=CURRENT_TIMESTAMP
        WHERE
          id=?
          AND rider_id=?
          AND status='arrived_at_dropoff'
      `).run(
        id,
        riderId
      );

      db.prepare(`
        INSERT INTO order_events(
          order_id,
          user_id,
          event,
          notes
        )
        VALUES(
          ?,
          ?,
          'otp_verified',
          'Rider successfully verified the customer delivery OTP.'
        )
      `).run(
        id,
        riderId
      );

    })();

    res.redirect('/rider');
  }
);
/* =========================================================
   RIDER DELIVERED
   OTP REQUIRED
========================================================= */

app.post(
  '/rider/order/:id/delivered',
  csrfCheck,
  requireRole('rider'),
  requireRiderOnline,
  (req, res) => {

    const id =
      Number(req.params.id);

    const riderId =
      req.session.user.id;

    const otp =
      String(
        req.body.delivery_otp || ''
      ).trim();

const order = db.prepare(`
  SELECT
    id,
    rider_id,
    status,
    payment_method,
    delivery_otp_verified
  FROM orders
      WHERE
        id=?
        AND rider_id=?
    `).get(
      id,
      riderId
    );

    if (!order) {
      return res.redirect('/rider');
    }
if (
  order.status !== 'arrived_at_dropoff'
) {
  return res.redirect('/rider');
}

if (
  Number(order.delivery_otp_verified || 0) !== 1
) {
  return res.status(400).send(
    page(
      'Delivery OTP Required',
      `
      <div class="card">

        <h2>
          Delivery OTP Required
        </h2>

        <p>
          The customer's delivery OTP must be
          verified before delivery can be completed.
        </p>

        ${alertBox(
          'Please return to the rider dashboard and verify the customer OTP first.'
        )}

        <a
          class="btn full"
          href="/rider"
        >
          Back to Rider Dashboard
        </a>

      </div>
      `,
      req
    )
  );
}

    

    /*
      Pay-on-delivery orders must have a confirmed
      customer payment before delivery can be completed.
    */
    if (
      order.payment_method === 'pay_on_delivery'
    ) {

      const financial =
        db.prepare(`
          SELECT
            customer_payment_status
          FROM financial_transactions
          WHERE order_id=?
        `).get(
          order.id
        );

      if (
        !financial ||
        financial.customer_payment_status !== 'paid'
      ) {

        return res.status(400).send(
          page(
            'Payment Required',
            `
            <div class="card">

              <h2>
                Customer Payment Required
              </h2>

              <p>
                This order uses
                <strong>Pay on Delivery</strong>.
              </p>

              <p class="muted">
                Customer payment must be confirmed
                before the delivery can be completed.
              </p>

              ${order.status === 'arrived_at_dropoff'
              ? `
                <form
                  method="post"
                  action="/rider/order/${order.id}/collect-payment"
                >
                  <input
                    type="hidden"
                    name="_csrf"
                    value="${csrf(req)}"
                  >

                  <button
                    type="submit"
                    class="btn full"
                  >
                    Collect Customer Payment
                  </button>
                </form>
              `
              : ''
              }

              <div style="margin-top:10px;">

                <a
                  class="btn full"
                  href="/rider"
                >
                  Back to Rider Dashboard
                </a>

              </div>

            </div>
            `,
            req
          )
        );
      }
    }

    const deliveryResult =
      db.prepare(`
        UPDATE orders
        SET
          status='delivered',
          delivered_at=CURRENT_TIMESTAMP,
          updated_at=CURRENT_TIMESTAMP
        WHERE
          id=?
          AND rider_id=?
          AND status IN (
            'on_the_way',
            'arrived_at_dropoff'
          )
      `).run(
        id,
        riderId
      );

    if (deliveryResult.changes > 0) {

      recordFinancialTransaction(id);

      db.prepare(`
        INSERT INTO order_events(
          order_id,
          user_id,
          event,
          notes
        )
        VALUES(
          ?,
          ?,
          'delivered',
          ?
        )
      `).run(
        id,
        riderId,
        'Rider confirmed delivery using customer OTP.'
      );
      db.prepare(`
        UPDATE order_chats
        SET
          status='closed',
          closed_at=CURRENT_TIMESTAMP
        WHERE
          order_id=?
          AND status='open'
      `).run(
        id
      );
    }

    res.redirect('/rider');
  }
);
