/* =========================================================
   RIDER DOCUMENT UPDATE
========================================================= */

app.post(
  '/rider/account/update-documents',
  requireRole('rider'),
  riderUpload.fields([
    { name: 'id_document', maxCount: 1 },
    { name: 'profile_photo', maxCount: 1 },
    { name: 'police_clearance', maxCount: 1 },
    { name: 'driving_license', maxCount: 1 },
    { name: 'motorcycle_insurance', maxCount: 1 }
  ]),
  csrfCheck,
  (req, res) => {

    const rider = db.prepare(`
      SELECT
        id,
        worker_type,
        motorcycle_plate,
        id_document_path,
        profile_photo_path,
        police_clearance_path,
        driving_license_path,
        motorcycle_insurance_path,
        reupload_request
      FROM users
      WHERE id=? AND role='rider'
    `).get(req.session.user.id);

    if (!rider) {
      return res.status(404).send(
        page(
          'Account Information',
          `
          <div class="card">
            ${alertBox('Rider account not found.')}
            <a class="btn" href="/rider/account">
              Back to Account
            </a>
          </div>
          `,
          req
        )
      );
    }

    const files = req.files || {};

    const updates = [];
    const values = [];

    const addFileUpdate = (
      fieldName,
      pathColumn,
      verificationColumn
    ) => {
      const uploaded = files[fieldName]?.[0];

      if (!uploaded) return false;

      updates.push(`${pathColumn}=?`);
      values.push(uploaded.path);

      updates.push(`${verificationColumn}=0`);

      return true;
    };

    const uploadedDocuments = new Set();

    if (
      addFileUpdate(
        'id_document',
        'id_document_path',
        'identity_verified'
      )
    ) {
      uploadedDocuments.add('identity');
    }

    if (
      addFileUpdate(
        'profile_photo',
        'profile_photo_path',
        'profile_verified'
      )
    ) {
      uploadedDocuments.add('profile');
    }

    if (
      addFileUpdate(
        'police_clearance',
        'police_clearance_path',
        'police_clearance_verified'
      )
    ) {
      uploadedDocuments.add('police');
    }

    if (
      addFileUpdate(
        'driving_license',
        'driving_license_path',
        'driving_license_verified'
      )
    ) {
      uploadedDocuments.add('license');
    }

    if (rider.worker_type === 'motorcycle') {

      const motorcyclePlate =
        String(req.body.motorcycle_plate || '').trim();

      if (motorcyclePlate) {
        updates.push('motorcycle_plate=?');
        values.push(motorcyclePlate);

        updates.push('motorcycle_verified=0');

        uploadedDocuments.add('motorcycle');
      }

      if (
        addFileUpdate(
          'motorcycle_insurance',
          'motorcycle_insurance_path',
          'insurance_verified'
        )
      ) {
        uploadedDocuments.add('insurance');
      }
    }

    if (!updates.length) {
      return res.redirect('/rider/account');
    }

    /*
      Any document re-uploaded by the rider must be reviewed again.
      The rider therefore cannot remain operational based on the
      previous approval.
    */
    updates.push("approval_status='pending'");
    updates.push('active=0');
    updates.push('online=0');

    /*
      Clear the Admin re-upload request only when the rider has
      actually submitted the requested document/information.
    */
    const requestedDocument =
      String(rider.reupload_request || '')
        .trim()
        .toLowerCase();

    if (
      requestedDocument &&
      uploadedDocuments.has(requestedDocument)
    ) {
      updates.push('reupload_request=NULL');
    }

    values.push(rider.id);

    db.prepare(`
      UPDATE users
      SET ${updates.join(', ')}
      WHERE id=?
    `).run(...values);

    return res.redirect('/rider/account');
  }
);
