app.post(
  '/admin/order/:id/deliver',
  csrfCheck,
  requireRole(
    'admin',
    'dispatcher'
  ),
  (req, res) => {

    const id = Number(req.params.id);

    const otp =
      String(
        req.body.delivery_otp || ''
      ).trim();

    const order = db.prepare(`
      SELECT
        id,
        status,
        delivery_otp
      FROM orders
      WHERE id=?
    `).get(id);

    if (!order) {
      return res.status(404).send('Order not found.');
    }

    if (
      order.status !== 'arrived_at_dropoff'
    ) {
      return res.redirect('/admin/orders');
    }

    /*
      If an OTP exists for the order,
      it must be entered correctly.
    */
    if (
      order.delivery_otp &&
      otp !== String(order.delivery_otp)
    ) {
      return res.status(400).send(
        page(
          'Delivery OTP error',
          `
          <div class="card">

            ${alertBox(
            'Incorrect delivery OTP. The order has NOT been marked delivered.'
          )}

            <a href="/admin/business-payment-requests" style="display:block;width:100%;box-sizing:border-box;padding:16px;margin-bottom:10px;color:#D4AF37;background:#0B294D;border:2px solid #D4AF37;border-radius:14px;text-decoration:none;font-size:17px;font-weight:800;">Payment Verification Center</a>

    <a
              class="btn"
              href="/admin/orders"
            >
              Back to Orders
            </a>

          </div>
          `,
          req
        )
      );
    }

    const deliveryResult = db.prepare(`
  UPDATE orders
  SET
    status='delivered',
    delivered_at=CURRENT_TIMESTAMP,
    updated_at=CURRENT_TIMESTAMP
  WHERE id=?
`).run(id);

    if (deliveryResult.changes > 0) {
      recordFinancialTransaction(id);
    }

    db.prepare(`
      INSERT INTO order_events(
        order_id,
        user_id,
        event,
        notes
      )
      VALUES(
        ?,
        ?,
        'delivered',
        ?
      )
    `).run(
      id,
      req.session.user.id,
      'Admin/dispatcher confirmed delivery.'
    );

    res.redirect('/admin/orders');
  }
);

