app.post(
  '/admin/operations/edit',
  requireRole('admin'),
  (req,res) => {

    const adminType =
      String(req.session.user.admin_type || '').trim().toLowerCase();

    if (adminType !== 'super') {
      return res.status(403).send('Access denied');
    }

    const settingKey =
      String(req.body.setting || '').trim();

    const value =
      String(req.body.value || '').trim();

    const allowedSettings = [
      'locus_fee_percentage',
      'rider_earnings_brackets',
      'rider_pickup_fee_brackets',
      'customer_pricing_brackets',
      'errand_service_fee'
    ];

    if (!allowedSettings.includes(settingKey)) {
      return res.status(400).send('Invalid Operations setting.');
    }

    if (!value) {
      return res.status(400).send('Setting value cannot be empty.');
    }

    let savedValue = value;

    if (settingKey === 'locus_fee_percentage') {
      const percentage = Number(value);

      if (!Number.isFinite(percentage) || percentage < 0 || percentage > 100) {
        return res.status(400).send(
          'Locus percentage must be between 0 and 100.'
        );
      }

      savedValue = String(percentage);

    } else if (settingKey === 'errand_service_fee') {
      const fee = Number(value);

      if (!Number.isFinite(fee) || fee < 0) {
        return res.status(400).send(
          'Errand service fee must be a valid amount of 0 or more.'
        );
      }

      savedValue = String(fee);

    } else {

      let parsed;

      try {
        parsed = JSON.parse(value);
      } catch {
        return res.status(400).send('Invalid JSON format.');
      }

      if (!Array.isArray(parsed) || parsed.length === 0) {
        return res.status(400).send(
          'Setting must contain at least one bracket.'
        );
      }

      savedValue = JSON.stringify(parsed);
    }

    db.prepare(`
      UPDATE locus_settings
      SET setting_value=?,
          updated_at=CURRENT_TIMESTAMP
      WHERE setting_key=?
    `).run(savedValue, settingKey);

    return res.redirect('/admin/operations');
  }
);

