app.post(
  '/finance/pay-rider/:transactionId',
  csrfCheck,
  requireRole('admin', 'finance'),
  (req, res) => {
    const user = req.session.user;

    if (
      user.role === 'admin' &&
      user.admin_type !== 'finance' &&
      user.admin_type !== 'super'
    ) {
      return res.status(403).send(
        page(
          'Access denied',
          `
          <div class="card">
            <h1>Access denied</h1>
            <p>You do not have permission to make rider payments.</p>
          </div>
          `,
          req
        )
      );
    }

    const transactionId = Number(req.params.transactionId);

    if (!Number.isInteger(transactionId) || transactionId <= 0) {
      return res.status(400).send('Invalid transaction ID.');
    }

    const transaction = db.prepare(`
      SELECT
        id,
        rider_earnings,
        rider_payment_status
      FROM financial_transactions
      WHERE id=?
      LIMIT 1
    `).get(transactionId);

    if (!transaction) {
      return res.status(404).send('Financial transaction not found.');
    }

    if (transaction.rider_payment_status !== 'unpaid') {
      return res.redirect('/finance/view/outstanding_rider_payments');
    }

    db.prepare(`
      UPDATE financial_transactions
      SET
        rider_payment_status='paid',
        updated_at=CURRENT_TIMESTAMP
      WHERE id=?
        AND rider_payment_status='unpaid'
    `).run(transactionId);

    return res.redirect('/finance/view/outstanding_rider_payments');
  }
);
