app.post(
  '/admin/order/:id/assign',
  csrfCheck,
  requireRole(
    'admin',
    'dispatcher'
  ),
  (req, res) => {

    const riderId =
      Number(req.body.rider_id);

    const orderId =
      Number(req.params.id);

    const rider = db.prepare(`
      SELECT
        id,
        name

      FROM users

      WHERE
        id=?
        AND role='rider'
        AND active=1
        AND COALESCE(
          approval_status,
          'approved'
        )='approved'
    `).get(
      riderId
    );

    if (!rider) {

      return res.status(400).send(
        page(
          'Assignment error',

          `
          <div class="card">

            ${alertBox(
            'Invalid or unavailable rider.'
          )}

            <a
              class="btn"
              href="/admin"
            >
              Back to operations
            </a>

          </div>
          `,

          req
        )
      );
    }

    /*
      Check that the order exists
      and is still waiting for dispatch.
    */

    const order = db.prepare(`
      SELECT
        id,
        status,
        rider_id

      FROM orders

      WHERE id=?
    `).get(
      orderId
    );

    if (
      !order ||
      order.status !== 'pending'
    ) {

      return res.status(400).send(
        page(
          'Assignment error',

          `
          <div class="card">

            ${alertBox(
            'This order is no longer available for assignment.'
          )}

            <a
              class="btn"
              href="/admin"
            >
              Back to operations
            </a>

          </div>
          `,

          req
        )
      );
    }

    /*
      If another rider currently has the offer,
      remove that offer before assigning
      the new rider.
    */

    if (order.rider_id) {

      db.prepare(`
        UPDATE order_dispatches

        SET
          status='rejected',
          responded_at=CURRENT_TIMESTAMP

        WHERE
          order_id=?
          AND rider_id=?
          AND status='offered'
      `).run(
        orderId,
        order.rider_id
      );
    }

    /*
      Assign the order to the selected rider.

      IMPORTANT:
      status remains "pending".

      The rider still has to ACCEPT.
    */

    db.prepare(`
      UPDATE orders

      SET
        rider_id=?,
        dispatcher_id=?,
        updated_at=CURRENT_TIMESTAMP

      WHERE
        id=?
        AND status='pending'
    `).run(
      riderId,
      req.session.user.id,
      orderId
    );

    /*
      Create a new dispatch offer.
    */

    db.prepare(`
      INSERT INTO order_dispatches(
        order_id,
        rider_id,
        status
      )
      VALUES(
        ?,
        ?,
        'offered'
      )
    `).run(
      orderId,
      riderId
    );

    /*
      Record the assignment in order history.
    */

    db.prepare(`
      INSERT INTO order_events(
        order_id,
        user_id,
        event,
        notes
      )
      VALUES(
        ?,
        ?,
        'assigned',
        ?
      )
    `).run(
      orderId,
      req.session.user.id,
      `Order manually assigned to rider ${rider.name}`
    );

    res.redirect('/admin');
  }
);
