app.get(
  '/admin/profile-photo',
  requireRole('admin'),
  (req, res) => {

    const admin = db.prepare(`
      SELECT
        id,
        role,
        profile_photo_path
      FROM users
      WHERE id=?
    `).get(req.session.user.id);

    if (!admin || admin.role !== 'admin') {
      return res.status(404).send('Admin not found.');
    }

    if (!admin.profile_photo_path) {
      return res.status(404).send('No profile photo uploaded.');
    }

    const adminsRoot = path.resolve(
      __dirname,
      'uploads',
      'admins'
    );

    const photoPath = path.resolve(
      admin.profile_photo_path
    );

    if (
      !photoPath.startsWith(
        adminsRoot + path.sep
      )
    ) {
      return res.status(403).send('Invalid profile photo path.');
    }

    if (!fs.existsSync(photoPath)) {
      return res.status(404).send('Profile photo not found.');
    }

    const buffer = fs.readFileSync(photoPath);

    let contentType = 'application/octet-stream';

    if (
      buffer.length >= 8 &&
      buffer[0] === 0x89 &&
      buffer[1] === 0x50 &&
      buffer[2] === 0x4e &&
      buffer[3] === 0x47
    ) {
      contentType = 'image/png';

    } else if (
      buffer.length >= 3 &&
      buffer[0] === 0xff &&
      buffer[1] === 0xd8 &&
      buffer[2] === 0xff
    ) {
      contentType = 'image/jpeg';

    } else if (
      buffer.length >= 12 &&
      buffer.slice(0, 4).toString('ascii') === 'RIFF' &&
      buffer.slice(8, 12).toString('ascii') === 'WEBP'
    ) {
      contentType = 'image/webp';

    } else {
      return res.status(415).send('Unsupported profile photo.');
    }

    res.set('Content-Type', contentType);
    res.set('Content-Disposition', 'inline');

    res.sendFile(photoPath);
  }
);
