app.post(
  '/dispatcher/profile',
  requireRole('dispatcher'),
  dispatcherPhotoUpload.single('profile_photo'),
  csrfCheck,
  (req, res) => {

    const dispatcher = db.prepare(`
      SELECT
        id,
        role,
        profile_photo_path
      FROM users
      WHERE id=?
      AND role='dispatcher'
    `).get(req.session.user.id);

    if (!dispatcher) {
      return res.status(404).send(
        'Dispatcher account not found.'
      );
    }

    const name = String(req.body.name || '').trim();
    const email = String(req.body.email || '')
      .trim()
      .toLowerCase();
    const phone = String(req.body.phone || '').trim();

    if (!name || !email || !phone) {

      if (req.file?.path) {
        try {
          fs.unlinkSync(req.file.path);
        } catch (_) {}
      }

      return res.redirect(
        '/dispatcher/profile?error=' +
        encodeURIComponent(
          'Name, email and phone are required.'
        )
      );
    }

    const existing = db.prepare(`
      SELECT id
      FROM users
      WHERE lower(email)=?
      AND id<>?
      AND deleted_at IS NULL
    `).get(
      email,
      dispatcher.id
    );

    if (existing) {

      if (req.file?.path) {
        try {
          fs.unlinkSync(req.file.path);
        } catch (_) {}
      }

      return res.redirect(
        '/dispatcher/profile?error=' +
        encodeURIComponent(
          'That email address is already in use.'
        )
      );
    }

    const oldPhoto =
      dispatcher.profile_photo_path;

    const newPhoto =
      req.file?.path || oldPhoto;

    db.prepare(`
      UPDATE users
      SET
        name=?,
        email=?,
        phone=?,
        profile_photo_path=?
      WHERE id=?
      AND role='dispatcher'
    `).run(
      name,
      email,
      phone,
      newPhoto,
      dispatcher.id
    );

    if (
      req.file?.path &&
      oldPhoto &&
      oldPhoto !== newPhoto
    ) {

      const dispatchersRoot = path.resolve(
        __dirname,
        'uploads',
        'dispatchers'
      );

      const oldPhotoPath =
        path.resolve(oldPhoto);

      if (
        oldPhotoPath.startsWith(
          dispatchersRoot + path.sep
        ) &&
        fs.existsSync(oldPhotoPath)
      ) {
        try {
          fs.unlinkSync(oldPhotoPath);
        } catch (err) {
          console.error(
            'Locus: failed to remove old dispatcher photo:',
            err.message
          );
        }
      }
    }

    req.session.user.name = name;
    req.session.user.email = email;

    res.redirect(
      '/dispatcher/profile?saved=1'
    );
  }
);
app.post(
  '/dispatcher/profile/password',
  requireRole('dispatcher'),
  csrfCheck,
  (req, res) => {

    const currentPassword =
      String(req.body.current_password || '');

    const newPassword =
      String(req.body.new_password || '');

    const confirmPassword =
      String(req.body.confirm_password || '');

    if (
      !currentPassword ||
      !newPassword ||
      !confirmPassword
    ) {
      return res.redirect(
        '/dispatcher/profile?error=' +
        encodeURIComponent(
          'All password fields are required.'
        )
      );
    }

    if (newPassword.length < 8) {
      return res.redirect(
        '/dispatcher/profile?error=' +
        encodeURIComponent(
          'New password must be at least 8 characters.'
        )
      );
    }

    if (newPassword !== confirmPassword) {
      return res.redirect(
        '/dispatcher/profile?error=' +
        encodeURIComponent(
          'New passwords do not match.'
        )
      );
    }

    const dispatcher = db.prepare(`
      SELECT
        id,
        role,
        password_hash
      FROM users
      WHERE id=?
      AND role='dispatcher'
    `).get(req.session.user.id);

    if (!dispatcher) {
      return res.status(404).send(
        'Dispatcher account not found.'
      );
    }

    if (
      !bcrypt.compareSync(
        currentPassword,
        dispatcher.password_hash
      )
    ) {
      return res.redirect(
        '/dispatcher/profile?error=' +
        encodeURIComponent(
          'Current password is incorrect.'
        )
      );
    }

    const newHash = bcrypt.hashSync(
      newPassword,
      12
    );

    db.prepare(`
      UPDATE users
      SET password_hash=?
      WHERE id=?
      AND role='dispatcher'
    `).run(
      newHash,
      dispatcher.id
    );

    res.redirect(
      '/dispatcher/profile?password=1'
    );
  }
);
app.post(
  '/admin/profile',
  requireRole('admin'),
  adminPhotoUpload.single('profile_photo'),
  csrfCheck,
  (req, res) => {

    const admin = db.prepare(`
      SELECT
        id,
        role,
        profile_photo_path
      FROM users
      WHERE id=?
      AND role='admin'
    `).get(req.session.user.id);

    if (!admin) {
      return res.status(404).send('Admin account not found.');
    }

    const name = String(req.body.name || '').trim();
    const email = String(req.body.email || '').trim().toLowerCase();
    const phone = String(req.body.phone || '').trim();

    if (!name || !email || !phone) {
      if (req.file?.path) {
        try {
          fs.unlinkSync(req.file.path);
        } catch (_) { }
      }

      return res.redirect(
        '/admin/profile?error=' +
        encodeURIComponent('Name, email and phone are required.')
      );
    }

    const existing = db.prepare(`
      SELECT id
      FROM users
      WHERE lower(email)=?
      AND id<>?
      AND deleted_at IS NULL
    `).get(
      email,
      admin.id
    );

    if (existing) {
      if (req.file?.path) {
        try {
          fs.unlinkSync(req.file.path);
        } catch (_) { }
      }

      return res.redirect(
        '/admin/profile?error=' +
        encodeURIComponent('That email address is already in use.')
      );
    }

    const oldPhoto = admin.profile_photo_path;
    const newPhoto = req.file?.path || oldPhoto;

    db.prepare(`
      UPDATE users
      SET
        name=?,
        email=?,
        phone=?,
        profile_photo_path=?
      WHERE id=?
      AND role='admin'
    `).run(
      name,
      email,
      phone,
      newPhoto,
      admin.id
    );

    if (
      req.file?.path &&
      oldPhoto &&
      oldPhoto !== newPhoto
    ) {
      const adminsRoot = path.resolve(
        __dirname,
        'uploads',
        'admins'
      );

      const oldPhotoPath = path.resolve(oldPhoto);

      if (
        oldPhotoPath.startsWith(
          adminsRoot + path.sep
        ) &&
        fs.existsSync(oldPhotoPath)
      ) {
        try {
          fs.unlinkSync(oldPhotoPath);
        } catch (err) {
          console.error(
            'Locus: failed to remove old admin photo:',
            err.message
          );
        }
      }
    }

    req.session.user.name = name;
    req.session.user.email = email;

    res.redirect('/admin/profile?saved=1');
  }
);


app.post(
  '/admin/profile/password',
  requireRole('admin'),
  csrfCheck,
  (req, res) => {

    const currentPassword =
      String(req.body.current_password || '');

    const newPassword =
      String(req.body.new_password || '');

    const confirmPassword =
      String(req.body.confirm_password || '');

    if (
      !currentPassword ||
      !newPassword ||
      !confirmPassword
    ) {
      return res.redirect(
        '/admin/profile?error=' +
        encodeURIComponent('All password fields are required.')
      );
    }

    if (newPassword.length < 8) {
      return res.redirect(
        '/admin/profile?error=' +
        encodeURIComponent('New password must be at least 8 characters.')
      );
    }

    if (newPassword !== confirmPassword) {
      return res.redirect(
        '/admin/profile?error=' +
        encodeURIComponent('New passwords do not match.')
      );
    }

    const admin = db.prepare(`
      SELECT
        id,
        role,
        password_hash
      FROM users
      WHERE id=?
      AND role='admin'
    `).get(req.session.user.id);

    if (!admin) {
      return res.status(404).send('Admin account not found.');
    }

    if (
      !bcrypt.compareSync(
        currentPassword,
        admin.password_hash
      )
    ) {
      return res.redirect(
        '/admin/profile?error=' +
        encodeURIComponent('Current password is incorrect.')
      );
    }

    const newHash = bcrypt.hashSync(
      newPassword,
      12
    );

    db.prepare(`
      UPDATE users
      SET password_hash=?
      WHERE id=?
      AND role='admin'
    `).run(
      newHash,
      admin.id
    );

    res.redirect('/admin/profile?password=1');
  }
);



