      "",
      "      <label style=\"display:block;margin-bottom:6px;font-weight:700;\">Account Type</label>",
      "      <select name=\"user_type\" required style=\"width:100%;box-sizing:border-box;margin-bottom:16px;padding:13px;border-radius:10px;border:1px solid #385578;background:#0b2545;color:#fff;\">",
      "        <option value=\"\">Select account type</option>",
      "        <option value=\"finance\">Finance</option>",
      "        <option value=\"accounts\">Accounts</option>",
      "        <option value=\"dispatcher\">Dispatcher</option>",
      "        <option value=\"other\">Other Admin</option>",
      "      </select>",
      "",
      "      <label style=\"display:block;margin-bottom:6px;font-weight:700;\">Temporary Password</label>",
      "      <input name=\"password\" type=\"password\" required minlength=\"8\" placeholder=\"Minimum 8 characters\" style=\"width:100%;box-sizing:border-box;margin-bottom:24px;padding:13px;border-radius:10px;border:1px solid #385578;background:#0b2545;color:#fff;\">",
      "",
