app.get(
  '/dispatcher/orders',
  requireRole('dispatcher'),
  (req, res) => {

    const businessNotifications = db.prepare(`
  SELECT
    id,
    title,
    message,
    notification_type,
    order_id,
    created_at
  FROM business_notifications
  WHERE
    business_user_id=?
    AND active=1
    AND read_at IS NULL
  ORDER BY id DESC
  LIMIT 10
`).all(req.session.user.id);

const orders = db.prepare(`
      SELECT
        o.id,
        o.order_number,
        o.service,
        o.status,
        o.pickup,
        o.dropoff,
        o.amount,
        o.created_at,
        o.updated_at,
        c.name AS customer_name,
        r.name AS rider_name,
        r.courier_id
      FROM orders o
      LEFT JOIN users c
        ON c.id = o.customer_id
      LEFT JOIN users r
        ON r.id = o.rider_id
      ORDER BY o.id DESC
    `).all();

    const e = (value) =>
      String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');

    const rows = orders.map(o => `
      <div
      class="card dispatcher-all-order-row"
        style="
          margin-bottom:12px;
          padding:16px;
        "
      >

        <div
          style="
            display:flex;
            justify-content:space-between;
            align-items:flex-start;
            gap:12px;
            flex-wrap:wrap;
          "
        >

          <div>

            <strong>
              ${e(o.order_number || ('Order #' + o.id))}
            </strong>

            <div class="muted" style="margin-top:5px;">
              ${e(o.service || 'Delivery')}
            </div>

          </div>

          <div class="pill">
            ${e(o.status || 'unknown')}
          </div>

        </div>

        <div style="margin-top:12px;">

          <div>
            <strong>Customer:</strong>
            ${e(o.customer_name || '?')}
          </div>

          <div>
            <strong>Rider:</strong>
            ${e(o.rider_name || 'Not assigned')}
            ${
              o.courier_id
                ? ` ? ${e(o.courier_id)}`
                : ''
            }
          </div>

          <div>
            <strong>Pickup:</strong>
            ${e(o.pickup || '?')}
          </div>

          <div>
            <strong>Drop-off:</strong>
            ${e(o.dropoff || '?')}
          </div>

          <div>
            <strong>Amount:</strong>
            KSh ${e(
              Number(o.amount || 0).toLocaleString(
                'en-KE',
                {
                  minimumFractionDigits:2,
                  maximumFractionDigits:2
                }
              )
            )}
          </div>

          <div class="muted" style="margin-top:6px;">
            Created:
            ${e(o.created_at || '?')}
          </div>

        </div>

        <div style="margin-top:14px;">

          <a
            class="btn"
            href="/dispatcher/order/${encodeURIComponent(o.id)}"
          >
            View
          </a>

        </div>

      </div>
    `).join('');

    res.send(
      page(
        'Dispatcher Orders',
        `

        <div class="page-head">

          <div>

            <div class="pill">
              DISPATCHER
            </div>

            <h1>
              All Orders
            </h1>

            <p>
              Monitor and manage Locus delivery orders.
            </p>

          </div>

          <a
            class="btn"
            href="/dispatcher"
          >
            Back to Dispatcher Dashboard
          </a>

        </div>

        <div
          style="
            width:100%;
            margin-top:20px;
            margin-bottom:16px;
          "
        >

          <input
            type="text"
            id="dispatcher-all-orders-search"
            placeholder="Search order, customer or rider..."
            autocomplete="off"
            style="
              display:block;
              width:100%;
              max-width:100%;
              box-sizing:border-box;
              padding:14px 16px;
              border:1px solid #cbd5e1;
              border-radius:10px;
              font-size:15px;
              color:#071C35;
              background:#ffffff;
              outline:none;
            "
          >

        </div>

        <div
          id="dispatcher-all-orders-results"
          style="
            width:100%;
          "
        >
          ${
            rows ||
            `
              <div class="card">
                <p class="muted">
                  No orders found.
                </p>
              </div>
            `
          }

        </div>  
        
        <script>
          document.addEventListener(
            'DOMContentLoaded',
            function () {

              const search =
                document.getElementById(
                  'dispatcher-all-orders-search'
                );

              if (!search) return;

              const orderRows =
                document.querySelectorAll(
                  '.dispatcher-all-order-row'
                );

              search.addEventListener(
                'input',
                function () {

                  const query =
                    this.value
                      .trim()
                      .toLowerCase();

                  orderRows.forEach(
                    function (row) {

                      const text =
                        row.textContent
                          .toLowerCase();

                      const match =
                        !query ||
                        text.includes(query);

                      row.style.display =
                        match ? 'block' : 'none';

                    }
                  );

                }
              );

            }
          );
        </script>
        `,
        req
      )
    );
  }
);

