/* =========================================================
   INBOX / CHAT MESSAGES
========================================================= */

db.exec(`
CREATE TABLE IF NOT EXISTS messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sender_id INTEGER NOT NULL,
  recipient_id INTEGER NOT NULL,
  message TEXT NOT NULL,
  read_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(sender_id) REFERENCES users(id),
  FOREIGN KEY(recipient_id) REFERENCES users(id)
);

CREATE INDEX IF NOT EXISTS idx_messages_recipient
ON messages(recipient_id);

CREATE INDEX IF NOT EXISTS idx_messages_sender
ON messages(sender_id);

CREATE INDEX IF NOT EXISTS idx_messages_created
ON messages(created_at);
`);
/* =========================================================
   RIDER STAFF CHAT STATUS
========================================================= */

db.exec(`
CREATE TABLE IF NOT EXISTS rider_staff_chats (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  rider_id INTEGER NOT NULL,

  staff_id INTEGER NOT NULL,

  status TEXT NOT NULL DEFAULT 'open',

  opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  closed_at TEXT,

  FOREIGN KEY(rider_id)
    REFERENCES users(id),

  FOREIGN KEY(staff_id)
    REFERENCES users(id),

  UNIQUE(rider_id, staff_id)
);

CREATE INDEX IF NOT EXISTS
idx_rider_staff_chats_rider
ON rider_staff_chats(rider_id);

CREATE INDEX IF NOT EXISTS
idx_rider_staff_chats_staff
ON rider_staff_chats(staff_id);

CREATE INDEX IF NOT EXISTS
idx_rider_staff_chats_status
ON rider_staff_chats(status);
`);
/* =========================================================
   RIDER / CUSTOMER ORDER CHAT
========================================================= */

db.exec(`
CREATE TABLE IF NOT EXISTS order_chats (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  order_id INTEGER NOT NULL,

  rider_id INTEGER NOT NULL,

  customer_id INTEGER NOT NULL,

  status TEXT NOT NULL DEFAULT 'open'
    CHECK(status IN ('open','closed')),

  opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  closed_at TEXT,

  FOREIGN KEY(order_id)
    REFERENCES orders(id),

  FOREIGN KEY(rider_id)
    REFERENCES users(id),

  FOREIGN KEY(customer_id)
    REFERENCES users(id),

  UNIQUE(order_id)
);

CREATE INDEX IF NOT EXISTS
idx_order_chats_order
ON order_chats(order_id);

CREATE INDEX IF NOT EXISTS
idx_order_chats_rider
ON order_chats(rider_id);

CREATE INDEX IF NOT EXISTS
idx_order_chats_customer
ON order_chats(customer_id);

CREATE INDEX IF NOT EXISTS
idx_order_chats_status
ON order_chats(status);
`);
/* =========================================================
   MESSAGE ORDER CHAT FIELD MIGRATION
========================================================= */

const messageColumns = db
  .prepare('PRAGMA table_info(messages)')
  .all()
  .map(c => c.name);

if (!messageColumns.includes('order_chat_id')) {
  db.exec(`
    ALTER TABLE messages
    ADD COLUMN order_chat_id INTEGER
    REFERENCES order_chats(id)
  `);
}
