app.get(
  '/customer/order/:orderId/chat',
  requireRole('customer'),
  (req, res) => {

    const errandServiceFee =
      Number(getLocusSetting('errand_service_fee', 500));
    const orderId = Number(req.params.orderId);
    const customerId = Number(req.session.user.id);

    if (!Number.isInteger(orderId)) {
      return res.status(400).send(
        page(
          'Invalid order',
          `
          <div class="card">
            ${alertBox('Invalid order.')}
            <a class="btn" href="/customer/orders" style="margin-top:12px;">
              Back to Orders
            </a>
          </div>
          `,
          req
        )
      );
    }

    const chat = db.prepare(`
      SELECT
        oc.id AS chat_id,
        oc.order_id,
        oc.rider_id,
        oc.customer_id,
        oc.status AS chat_status,
        o.order_number,
        o.status AS order_status,
        o.service,
        r.name AS rider_name,
        r.phone AS rider_phone
      FROM order_chats oc
      INNER JOIN orders o ON o.id=oc.order_id
      LEFT JOIN users r ON r.id=oc.rider_id
      WHERE oc.order_id=? AND oc.customer_id=?
    `).get(orderId, customerId);

    if (!chat) {
      return res.status(404).send(
        page(
          'Order chat',
          `
          <div class="card">
            ${alertBox('Order chat not found or you are not authorised to access it.')}
            <a class="btn" href="/customer/orders" style="margin-top:12px;">
              Back to Orders
            </a>
          </div>
          `,
          req
        )
      );
    }

    const messages = db.prepare(`
      SELECT
        m.id,
        m.sender_id,
        m.recipient_id,
        m.message,
        m.read_at,
        m.created_at,
        u.name AS sender_name
      FROM messages m
      LEFT JOIN users u ON u.id=m.sender_id
      WHERE m.order_chat_id=?
      ORDER BY m.id ASC
    `).all(chat.chat_id);

    db.prepare(`
      UPDATE messages
      SET read_at=CURRENT_TIMESTAMP
      WHERE order_chat_id=?
        AND recipient_id=?
        AND read_at IS NULL
    `).run(chat.chat_id, customerId);

    const messageRows = messages.map(m => `
      <div style="
        margin-bottom:10px;
        padding:11px 13px;
        border-radius:12px;
        background:${Number(m.sender_id) === customerId ? '#071C35' : '#f3f4f6'};
        color:${Number(m.sender_id) === customerId ? '#ffffff' : '#111827'};
      ">
        <strong>${e(Number(m.sender_id) === customerId ? 'You' : (m.sender_name || 'Rider'))}</strong>
        <div style="margin-top:5px;white-space:pre-wrap;">
          ${e(m.message || '')}
        </div>
        <small style="display:block;margin-top:6px;opacity:.7;">
          ${e(m.created_at || '')}
        </small>
      </div>
    `).join('');

    const canSend =
      chat.chat_status === 'open' &&
      Number(chat.rider_id) > 0 &&
      Number(chat.rider_id) !== customerId;

    res.send(
      page(
        'Chat with Rider',
        `
        <div class="page-head">
          <div>
            <div class="pill">ORDER CHAT</div>
            <h1>Chat with Rider</h1>
            <p>
              Order ${e(
                chat.order_number ||
                ('LOC#' + String(chat.order_id).padStart(8, '0'))
              )}
            </p>
          </div>

          <a class="btn" href="/customer/orders">
            Back to Orders
          </a>
        </div>

        <div class="card">
          <div style="
            margin-bottom:14px;
            padding:12px;
            background:#f8fafc;
            border-radius:10px;
          ">
            <strong>Rider:</strong>
            ${e(chat.rider_name || 'Rider')}

            ${
              chat.rider_phone
                ? `
                  <div style="margin-top:4px;">
                    <strong>Phone:</strong>
                    ${e(chat.rider_phone)}
                  </div>
                `
                : ''
            }

            <div style="margin-top:4px;">
              <strong>Status:</strong>
              ${e(String(chat.order_status || '').replace(/_/g, ' '))}
            </div>
          </div>

          <div style="
            max-height:460px;
            overflow-y:auto;
            margin-bottom:16px;
          ">
            ${
              messageRows ||
              `
              <div style="
                padding:20px;
                text-align:center;
                color:#6b7280;
              ">
                No messages yet.
              </div>
              `
            }
          </div>

          ${
            canSend
              ? `
                <form method="POST" action="/customer/order/${chat.order_id}/chat">
                  <input
                    type="hidden"
                    name="_csrf"
                    value="${csrf(req)}"
                  >

                  <textarea
                    name="message"
                    rows="3"
                    maxlength="2000"
                    required
                    placeholder="Type a message to your rider..."
                    style="
                      width:100%;
                      box-sizing:border-box;
                      padding:11px;
                      border:1px solid #cbd5e1;
                      border-radius:9px;
                      resize:vertical;
                    "
                  ></textarea>

                  <button
                    type="submit"
                    class="btn"
                    style="margin-top:10px;"
                  >
                    Send Message
                  </button>
                </form>
              `
              : `
                <div style="
                  padding:12px;
                  border-radius:9px;
                  background:#f3f4f6;
                  color:#6b7280;
                  text-align:center;
                ">
                  This order chat is closed.
                </div>
              `
          }
        </div>
        `,
        req
      )
    );
  }
);

app.post(
  '/customer/order/:orderId/chat',
  requireRole('customer'),
  csrfCheck,
  (req, res) => {
    const orderId = Number(req.params.orderId);
    const customerId = Number(req.session.user.id);
    const message = String(req.body.message || '').trim();

    if (!Number.isInteger(orderId)) {
      return res.status(400).send(
        page(
          'Invalid order',
          `
          <div class="card">
            ${alertBox('Invalid order.')}
            <a class="btn" href="/customer/orders">Back to Orders</a>
          </div>
          `,
          req
        )
      );
    }

    if (!message || message.length > 2000) {
      return res.status(400).send(
        page(
          'Invalid message',
          `
          <div class="card">
            ${alertBox('Please enter a message of 1 to 2000 characters.')}
            <a class="btn" href="/customer/order/${orderId}/chat">
              Back to Chat
            </a>
          </div>
          `,
          req
        )
      );
    }

    const chat = db.prepare(`
      SELECT id, order_id, rider_id, customer_id, status
      FROM order_chats
      WHERE order_id=? AND customer_id=?
    `).get(orderId, customerId);

    if (!chat) {
      return res.status(404).send(
        page(
          'Order chat',
          `
          <div class="card">
            ${alertBox('Order chat not found or you are not authorised to use it.')}
            <a class="btn" href="/customer/orders">Back to Orders</a>
          </div>
          `,
          req
        )
      );
    }

    if (
      chat.status !== 'open' ||
      !Number.isInteger(Number(chat.rider_id)) ||
      Number(chat.rider_id) <= 0
    ) {
      return res.status(409).send(
        page(
          'Order chat closed',
          `
          <div class="card">
            ${alertBox('This order chat is closed.')}
            <a class="btn" href="/customer/order/${orderId}/chat">
              View Chat
            </a>
          </div>
          `,
          req
        )
      );
    }

    db.prepare(`
      INSERT INTO messages (
        sender_id,
        recipient_id,
        message,
        order_chat_id
      )
      VALUES (?, ?, ?, ?)
    `).run(
      customerId,
      Number(chat.rider_id),
      message,
      Number(chat.id)
    );

    res.redirect(`/customer/order/${orderId}/chat`);
  }
);


/* =========================================================
   RIDER CHAT STAFF OPEN / CLOSE
========================================================= */

function isRiderChatStaff(req) {
  const user = req.session?.user;

  if (!user) {
    return false;
  }

  if (user.role === 'dispatcher') {
    return true;
  }

  if (user.role === 'admin') {
    const adminType =
      String(user.admin_type || '')
        .trim()
        .toLowerCase();

    return [
      'super',
      'finance',
      'accounts',
      'dispatcher'
    ].includes(adminType);
  }

  return false;
}


/* ---------------------------------------------------------
   OPEN / REOPEN RIDER CHAT
--------------------------------------------------------- */

app.post(
  '/staff/rider-chat/:riderId/open',
  csrfCheck,
  (req, res) => {

    if (!isRiderChatStaff(req)) {
      return res.status(403).send(
        page(
          'Access denied',
          `
          <div class="card">
            ${alertBox('You are not authorised to access rider chats.')}
          </div>
          `,
          req
        )
      );
    }

    const riderId =
      Number(req.params.riderId);

    if (!Number.isInteger(riderId)) {
      return res.redirect('/dispatcher');
    }

    const rider = db.prepare(`
      SELECT
        id,
        name,
        role
      FROM users
      WHERE id=?
        AND role='rider'
    `).get(riderId);

    if (!rider) {
      return res.redirect('/dispatcher');
    }

    const staffId =
      req.session.user.id;

    db.prepare(`
      INSERT INTO rider_staff_chats (
        rider_id,
        staff_id,
        status,
        opened_at,
        closed_at
      )
      VALUES (
        ?,
        ?,
        'open',
        CURRENT_TIMESTAMP,
        NULL
      )
      ON CONFLICT(rider_id, staff_id)
      DO UPDATE SET
        status='open',
        opened_at=CURRENT_TIMESTAMP,
        closed_at=NULL
    `).run(
      riderId,
      staffId
    );

    /*
      If this is a dispatcher, also keep the existing
      dispatcher chat assignment connected to the rider chat.
    */

    if (req.session.user.role === 'dispatcher') {

      db.prepare(`
        INSERT INTO dispatcher_chat_assignments (
          chat_user_id,
          dispatcher_id,
          claimed_at
        )
        VALUES (
          ?,
          ?,
          CURRENT_TIMESTAMP
        )
        ON CONFLICT(chat_user_id)
        DO UPDATE SET
          dispatcher_id=excluded.dispatcher_id,
          claimed_at=CURRENT_TIMESTAMP
      `).run(
        riderId,
        staffId
      );
    }

    if (req.session.user.role === 'dispatcher') {
      return res.redirect(
        `/dispatcher/chat/${riderId}`
      );
    }

    return res.redirect('/admin/inbox');
  }
);


/* ---------------------------------------------------------
   CLOSE RIDER CHAT
--------------------------------------------------------- */

app.post(
  '/staff/rider-chat/:riderId/close',
  csrfCheck,
  (req, res) => {

    if (!isRiderChatStaff(req)) {
      return res.status(403).send(
        page(
          'Access denied',
          `
          <div class="card">
            ${alertBox('You are not authorised to access rider chats.')}
          </div>
          `,
          req
        )
      );
    }

    const riderId =
      Number(req.params.riderId);

    if (!Number.isInteger(riderId)) {
      return res.redirect('/dispatcher');
    }

    const rider = db.prepare(`
      SELECT
        id,
        name,
        role
      FROM users
      WHERE id=?
        AND role='rider'
    `).get(riderId);

    if (!rider) {
      return res.redirect('/dispatcher');
    }

    const staffId =
      req.session.user.id;

    db.prepare(`
      UPDATE rider_staff_chats
      SET
        status='closed',
        closed_at=CURRENT_TIMESTAMP
      WHERE
        rider_id=?
        AND staff_id=?
    `).run(
      riderId,
      staffId
    );

    if (req.session.user.role === 'dispatcher') {
      return res.redirect(
        `/dispatcher/chat/${riderId}`
      );
    }

    return res.redirect('/admin/inbox');
  }
);
