db.exec(`
CREATE TABLE IF NOT EXISTS dispatcher_chat_assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  chat_user_id INTEGER NOT NULL,

  dispatcher_id INTEGER NOT NULL,

  claimed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  UNIQUE(chat_user_id),

  FOREIGN KEY(chat_user_id)
    REFERENCES users(id),

  FOREIGN KEY(dispatcher_id)
    REFERENCES users(id)
);

CREATE INDEX IF NOT EXISTS
idx_dispatcher_chat_assignment_dispatcher
ON dispatcher_chat_assignments(dispatcher_id);

CREATE INDEX IF NOT EXISTS
idx_dispatcher_chat_assignment_user
ON dispatcher_chat_assignments(chat_user_id);
`);
/* =========================================================
   RIDER ACCOUNT DELETION REQUESTS
========================================================= */

db.exec(`
CREATE TABLE IF NOT EXISTS account_deletion_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  rider_id INTEGER NOT NULL,

  reason TEXT,

  status TEXT NOT NULL DEFAULT 'pending',

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  reviewed_at TEXT,

  reviewed_by INTEGER,

  FOREIGN KEY(rider_id) REFERENCES users(id),
  FOREIGN KEY(reviewed_by) REFERENCES users(id)
);

CREATE INDEX IF NOT EXISTS
idx_account_deletion_requests_rider
ON account_deletion_requests(rider_id);

CREATE INDEX IF NOT EXISTS
idx_account_deletion_requests_status
ON account_deletion_requests(status);

CREATE INDEX IF NOT EXISTS
idx_account_deletion_requests_created
ON account_deletion_requests(created_at);
`);


