app.post(
  '/admin/rider-notifications',
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const recipient =
      String(req.body.recipient || 'all').trim();

    const title =
      String(req.body.title || '').trim();

    const message =
      String(req.body.message || '').trim();

    const notificationType =
      String(
        req.body.notification_type || 'announcement'
      ).trim();

    if (
      title.length < 2 ||
      title.length > 120 ||
      message.length < 2 ||
      message.length > 2000
    ) {
      return res.redirect(
        '/admin/rider-notifications'
      );
    }

    const allowedTypes = [
      'promotion',
      'announcement',
      'account',
      'delivery'
    ];

    if (!allowedTypes.includes(notificationType)) {
      return res.redirect(
        '/admin/rider-notifications'
      );
    }

    let riderId = null;

    if (recipient === 'specific') {

      riderId =
        Number(req.body.rider_id);

      if (!Number.isInteger(riderId)) {
        return res.redirect(
          '/admin/rider-notifications'
        );
      }

      const rider = db.prepare(`
        SELECT id
        FROM users
        WHERE
          id=?
          AND role='rider'
          AND deleted_at IS NULL
      `).get(riderId);

      if (!rider) {
        return res.redirect(
          '/admin/rider-notifications'
        );
      }
    }

    db.prepare(`
      INSERT INTO rider_notifications(
        rider_id,
        title,
        message,
        notification_type,
        active,
        created_by
      )
      VALUES(?,?,?,?,1,?)
    `).run(
      riderId,
      title,
      message,
      notificationType,
      req.session.user.id
    );

    res.redirect(
      '/admin/rider-notifications'
    );
  }
);

app.post(
  '/admin/rider-notifications/:id/toggle',
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const id =
      Number(req.params.id);

    if (!Number.isInteger(id)) {
      return res.redirect(
        '/admin/rider-notifications'
      );
    }

    db.prepare(`
      UPDATE rider_notifications
      SET
        active =
          CASE
            WHEN active=1 THEN 0
            ELSE 1
          END
      WHERE id=?
    `).run(id);

    res.redirect(
      '/admin/rider-notifications'
    );
  }
);

app.post(
  '/admin/rider-notifications/:id/delete',
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const id =
      Number(req.params.id);

    if (!Number.isInteger(id)) {
      return res.redirect(
        '/admin/rider-notifications'
      );
    }

    db.prepare(`
      DELETE FROM rider_notifications
      WHERE id=?
    `).run(id);

    res.redirect(
      '/admin/rider-notifications'
    );
  }
);

