/* =========================================================
   ADMIN SEND MESSAGE
========================================================= */

app.post(
  '/admin/messages/send',
  requireRole('admin'),
  csrfCheck,
  (req, res) => {

    const user = req.session.user;

    const group =
      String(req.body.group || '')
        .trim()
        .toLowerCase();

    const mode =
      String(req.body.mode || '')
        .trim()
        .toLowerCase();

    const message =
      String(req.body.message || '').trim();

    const validGroups = [
      'admins',
      'dispatchers',
      'accounts',
      'finances',
      'customers',
      'riders'
    ];

    if (
      !validGroups.includes(group) ||
      !['all', 'select'].includes(mode) ||
      !message
    ) {
      return res.status(400).send(
        'Invalid message request.'
      );
    }

    let recipients = [];

    if (group === 'admins') {

      recipients = db.prepare(`
        SELECT id
        FROM users
        WHERE
          role='admin'
          AND active=1
          AND id<>?
          AND COALESCE(admin_type,'') NOT IN (
            'accounts',
            'finance'
          )
      `).all(user.id);

    } else if (group === 'dispatchers') {

      recipients = db.prepare(`
        SELECT id
        FROM users
        WHERE
          role='dispatcher'
          AND active=1
      `).all();

    } else if (group === 'accounts') {

      recipients = db.prepare(`
        SELECT id
        FROM users
        WHERE
          role='admin'
          AND admin_type='accounts'
          AND active=1
      `).all();

    } else if (group === 'finances') {

      recipients = db.prepare(`
        SELECT id
        FROM users
        WHERE
          role='admin'
          AND admin_type='finance'
          AND active=1
      `).all();

    } else if (group === 'customers') {

      recipients = db.prepare(`
        SELECT id
        FROM users
        WHERE
          role='customer'
          AND active=1
      `).all();

    } else if (group === 'riders') {

      recipients = db.prepare(`
        SELECT id
        FROM users
        WHERE
          role='rider'
          AND active=1
      `).all();

    }

    if (mode === 'select') {

      let selectedIds =
        req.body.recipient_ids || [];

      if (!Array.isArray(selectedIds)) {
        selectedIds = [selectedIds];
      }

      const allowedIds =
        new Set(
          recipients.map(
            r => Number(r.id)
          )
        );

      const selectedRecipients =
        selectedIds
          .map(Number)
          .filter(id =>
            Number.isInteger(id) &&
            allowedIds.has(id)
          );

      recipients =
        recipients.filter(r =>
          selectedRecipients.includes(
            Number(r.id)
          )
        );
    }

    if (!recipients.length) {
      return res.status(400).send(
        'No valid recipients were selected.'
      );
    }

    const insertMessage = db.prepare(`
      INSERT INTO messages (
        sender_id,
        recipient_id,
        message
      )
      VALUES (?, ?, ?)
    `);

    const sendMessages =
      db.transaction(() => {

        for (const recipient of recipients) {

          insertMessage.run(
            user.id,
            recipient.id,
            message
          );

        }

      });

    sendMessages();

    res.redirect(
      '/admin/messages?section=messages'
    );
  }
);
/* =========================================================
   ADMIN INDIVIDUAL MESSAGE THREAD
========================================================= */

app.get(
  '/admin/messages/thread/:id',
  requireRole('admin'),
  (req, res) => {

    const user = req.session.user;

    const contactId =
      Number(req.params.id);

    if (
      !Number.isInteger(contactId) ||
      contactId <= 0 ||
      contactId === Number(user.id)
    ) {
      return res.status(400).send(
        'Invalid conversation.'
      );
    }

    const contact = db.prepare(`
      SELECT
        id,
        name,
        email,
        role,
        admin_type,
        active
      FROM users
      WHERE id=?
    `).get(contactId);

    if (!contact) {
      return res.status(404).send(
        'User not found.'
      );
    }

    const messages = db.prepare(`
      SELECT
        m.id,
        m.sender_id,
        m.recipient_id,
        m.message,
        m.created_at,
        s.name AS sender_name
      FROM messages m
      LEFT JOIN users s
        ON s.id = m.sender_id
      WHERE
        (
          m.sender_id = ?
          AND m.recipient_id = ?
        )
        OR
        (
          m.sender_id = ?
          AND m.recipient_id = ?
        )
      ORDER BY
        m.id ASC
    `).all(
      user.id,
      contactId,
      contactId,
      user.id
    );

    db.prepare(`
      UPDATE messages
      SET read_at=CURRENT_TIMESTAMP
      WHERE
        sender_id=?
        AND recipient_id=?
        AND read_at IS NULL
    `).run(
      contactId,
      user.id
    );

    const messageBubbles =
      messages.length
        ? messages.map(m => {

            const sent =
              Number(m.sender_id) ===
              Number(user.id);

            return `
              <div
                style="
                  display:flex;
                  justify-content:${
                    sent
                      ? 'flex-end'
                      : 'flex-start'
                  };
                  margin-bottom:14px;
                "
              >

                <div
                  style="
                    max-width:78%;
                  "
                >

                  <div
                    style="
                      font-size:13px;
                      font-weight:700;
                      margin-bottom:4px;
                    "
                  >
                    ${e(
                      sent
                        ? 'You'
                        : (
                            m.sender_name ||
                            contact.name ||
                            'User'
                          )
                    )}
                  </div>

                  <div
                    class="muted"
                    style="
                      font-size:12px;
                      margin-bottom:5px;
                    "
                  >
                    ${e(
                      m.created_at || ''
                    )}
                  </div>

                  <div
                    style="
                      background:${
                        sent
                          ? '#ffffff'
                          : '#D4AF37'
                      };
                      color:#071C35;
                      padding:11px 14px;
                      border-radius:14px;
                      white-space:pre-wrap;
                      overflow-wrap:anywhere;
                      box-shadow:
                        0 2px 8px
                        rgba(0,0,0,.15);
                    "
                  >
                    ${e(
                      m.message || ''
                    )}
                  </div>

                </div>

              </div>
            `;

          }).join('')
        : `
          <p class="muted">
            No messages in this conversation yet.
          </p>
        `;

    res.send(
      page(
        'Message Thread',
        `

        <div class="page-head">

          <div>

            <div class="pill">
              MESSAGE
            </div>

            <h1>
              ${e(
                contact.name ||
                'User'
              )}
            </h1>

            <p>
              Your private conversation with this user.
            </p>

          </div>

        </div>


        <div
          class="card"
          style="
            max-width:850px;
            margin:0 auto;
          "
        >

          <div
            style="
              padding-bottom:14px;
              border-bottom:
                1px solid
                rgba(255,255,255,.10);
              margin-bottom:18px;
            "
          >

            <strong>
              ${e(
                contact.name ||
                'User'
              )}
            </strong>

            ${
              contact.email
                ? `
                  <div
                    class="muted"
                    style="
                      margin-top:3px;
                      font-size:13px;
                    "
                  >
                    ${e(contact.email)}
                  </div>
                `
                : ''
            }

          </div>


          <div
            style="
              display:flex;
              flex-direction:column;
            "
          >

            ${messageBubbles}

          </div>


          <form
            method="POST"
            action="/admin/messages/thread/${Number(contactId)}"
            style="
              margin-top:20px;
              padding-top:16px;
              border-top:
                1px solid
                rgba(255,255,255,.10);
            "
          >

            <input
              type="hidden"
              name="_csrf"
              value="${csrf(req)}"
            >

            <textarea
              name="message"
              rows="4"
              required
              maxlength="5000"
              placeholder="Write a message..."
              style="
                width:100%;
                box-sizing:border-box;
              "
            ></textarea>

            <div
              style="
                display:flex;
                gap:10px;
                flex-wrap:wrap;
                margin-top:10px;
              "
            >

              <button
                type="submit"
                class="btn"
              >
                Send
              </button>

              <a
                href="/admin/messages?section=messages"
                class="btn ghost"
              >
                Back to Messages
              </a>

            </div>

          </form>

        </div>

        `,
        req
      )
    );
  }
);


