app.post(
  '/admin/messages/thread/:id',
  requireRole('admin'),
  csrfCheck,
  (req, res) => {

    const user = req.session.user;

    const contactId =
      Number(req.params.id);

    const message =
      String(
        req.body.message || ''
      ).trim();

    if (
      !Number.isInteger(contactId) ||
      contactId <= 0 ||
      contactId === Number(user.id)
    ) {
      return res.status(400).send(
        'Invalid conversation.'
      );
    }

    if (!message) {
      return res.status(400).send(
        'Message cannot be empty.'
      );
    }

    if (message.length > 5000) {
      return res.status(400).send(
        'Message is too long.'
      );
    }

    const contact = db.prepare(`
      SELECT id
      FROM users
      WHERE id=?
    `).get(contactId);

    if (!contact) {
      return res.status(404).send(
        'User not found.'
      );
    }

    db.prepare(`
      INSERT INTO messages (
        sender_id,
        recipient_id,
        message
      )
      VALUES (?, ?, ?)
    `).run(
      user.id,
      contactId,
      message
    );

    res.redirect(
      `/admin/messages/thread/${Number(contactId)}`
    );
  }
);
