/* ---------------------------------------------------------
   ADMIN / FINANCE CHAT
--------------------------------------------------------- */

app.get(
  '/admin/finance-chat',
  requireRole('admin'),
  (req, res) => {

    const user = req.session.user;

    const financeUsers = db.prepare(`
      SELECT
        id,
        name,
        email
      FROM users
      WHERE role='admin'
        AND admin_type='finance'
        AND active=1
      ORDER BY name ASC
    `).all();

    const financeIds = financeUsers.map(
      u => Number(u.id)
    );

    const messages = financeIds.length
      ? db.prepare(`
          SELECT
            m.id,
            m.sender_id,
            m.recipient_id,
            m.message,
            m.created_at,
            sender.name AS sender_name
          FROM messages m
          LEFT JOIN users sender
            ON sender.id=m.sender_id
          WHERE
            (
              m.sender_id=?
              AND m.recipient_id IN (
                ${financeIds.map(() => '?').join(',')}
              )
            )
            OR
            (
              m.recipient_id=?
              AND m.sender_id IN (
                ${financeIds.map(() => '?').join(',')}
              )
            )
          ORDER BY m.id ASC
        `).all(
          user.id,
          ...financeIds,
          user.id,
          ...financeIds
        )
      : [];

    db.prepare(`
      UPDATE messages
      SET read_at=CURRENT_TIMESTAMP
      WHERE
        recipient_id=?
        AND sender_id IN (
          ${financeIds.length
            ? financeIds.map(() => '?').join(',')
            : 'NULL'}
        )
        AND read_at IS NULL
    `).run(
      ...(financeIds.length
        ? [user.id, ...financeIds]
        : [user.id])
    );

    const messageRows = messages.map(m => `
      <div
        style="
          margin-bottom:12px;
          padding:12px 14px;
          border-radius:10px;
          background:${
            Number(m.sender_id) === Number(user.id)
              ? 'rgba(212,175,55,.12)'
              : 'rgba(255,255,255,.06)'
          };
          border:1px solid rgba(255,255,255,.10);
        "
      >

        <div
          style="
            display:flex;
            justify-content:space-between;
            gap:12px;
          "
        >
          <strong>
            ${e(m.sender_name || 'User')}
          </strong>

          <small class="muted">
            ${e(m.created_at || '')}
          </small>
        </div>

        <div
          style="
            margin-top:7px;
            white-space:pre-wrap;
          "
        >
          ${e(m.message)}
        </div>

      </div>
    `).join('');

    res.send(
      page(
        'Finance Communication',
        `
        <div class="page-head">

          <div>

            <div class="pill">
              FINANCE
            </div>

            <h1>
              Finance Communication
            </h1>

            <p>
              Communicate directly with the Finance
              department.
            </p>

          </div>

        </div>

        <div class="card">

          <h2>
            Conversation with Finance
          </h2>

          <div
            style="
              margin-top:16px;
              max-height:420px;
              overflow-y:auto;
            "
          >
            ${
              messageRows ||
              `
              <p class="muted">
                No messages yet.
              </p>
              `
            }
          </div>

          <form
            method="POST"
            action="/admin/finance-chat"
            style="margin-top:18px;"
          >

            <input
              type="hidden"
              name="_csrf"
              value="${csrf(req)}"
            >

            <textarea
              name="message"
              rows="4"
              required
              maxlength="5000"
              placeholder="Write a message to Finance..."
              style="
                width:100%;
                box-sizing:border-box;
              "
            ></textarea>

            <button
              type="submit"
              class="btn"
              style="margin-top:10px;"
            >
              Send to Finance
            </button>

          </form>

        </div>

        <div style="margin-top:18px;">

          <a
            class="btn ghost"
            href="/admin"
          >
            Back to Admin
          </a>

        </div>
        `,
        req
      )
    );
  }
);

