app.get(
  '/finance/department-chat',
  requireRole('admin'),
  (req, res) => {

    const user = req.session.user;

    if (
      user.admin_type !== 'finance' &&
      user.admin_type !== 'super'
    ) {
      return res.status(403).send(
        'Access denied.'
      );
    }

    const departments = db.prepare(`
      SELECT
        id,
        name,
        email,
        admin_type
      FROM users
      WHERE active=1
        AND (
          (
            role='admin'
            AND admin_type IN ('super','other')
          )
          OR role='dispatcher'
          OR (
            role='admin'
            AND admin_type='accounts'
          )
          OR (
            role='admin'
            AND admin_type='finance'
          )
        )
      ORDER BY
        CASE
          WHEN role='admin'
           AND admin_type='accounts'
          THEN 1
          WHEN role='dispatcher'
          THEN 2
          ELSE 3
        END,
        name ASC
    `).all();

    const rows = departments.map(d => {

      const unread = db.prepare(`
        SELECT COUNT(*) AS count
        FROM messages
        WHERE
          sender_id=?
          AND recipient_id=?
          AND read_at IS NULL
      `).get(
        d.id,
        user.id
      );

      const last = db.prepare(`
        SELECT
          message,
          created_at
        FROM messages
        WHERE
          (
            sender_id=?
            AND recipient_id=?
          )
          OR
          (
            sender_id=?
            AND recipient_id=?
          )
        ORDER BY id DESC
        LIMIT 1
      `).get(
        d.id,
        user.id,
        user.id,
        d.id
      );

      return `
        <a
          href="/finance/department-chat/${Number(d.id)}"
          class="card"
          style="
            display:block;
            text-decoration:none;
            color:inherit;
            margin-bottom:12px;
          "
        >

          <div class="page-head">

            <div>

              <div class="pill">
                ${e(
                  d.role === 'dispatcher'
                    ? 'DISPATCHER'
                    : String(
                        d.admin_type || 'ADMIN'
                      ).toUpperCase()
                )}
              </div>

              <h2>
                ${e(d.name || 'Staff')}
              </h2>

              <p class="muted">
                ${e(d.email || '')}
              </p>

            </div>

            ${
              Number(unread.count || 0) > 0
                ? `
                  <span class="pill">
                    ${Number(unread.count)}
                    New
                  </span>
                `
                : ''
            }

          </div>

          <p
            style="
              margin:0;
              white-space:nowrap;
              overflow:hidden;
              text-overflow:ellipsis;
            "
          >
            ${e(last?.message || 'No messages yet.')}
          </p>

        </a>
      `;
    }).join('');

    res.send(
      page(
        'Department Communications',
        `
        <div class="page-head">

          <div>

            <div class="pill">
              FINANCE
            </div>

            <h1>
              Department Communications
            </h1>

            <p>
              Communicate with Admin, Dispatcher and
              Accounts.
            </p>

          </div>

        </div>

        ${
          rows ||
          `
          <div class="card">
            <p class="muted">
              No department accounts found.
            </p>
          </div>
          `
        }

        <div style="margin-top:18px;">

          <a
            class="btn ghost"
            href="/finance"
          >
            Back to Finance
          </a>

        </div>
        `,
        req
      )
    );
  }
);

app.get(
  '/finance/department-chat/:id',
  requireRole('admin'),
  (req, res) => {

    const user = req.session.user;

    if (
      user.admin_type !== 'finance' &&
      user.admin_type !== 'super'
    ) {
      return res.status(403).send(
        'Access denied.'
      );
    }

    const recipientId =
      Number(req.params.id);

    const recipient = db.prepare(`
      SELECT
        id,
        name,
        email,
        role,
        admin_type
      FROM users
      WHERE id=?
        AND active=1
      LIMIT 1
    `).get(recipientId);

    if (!recipient) {
      return res.status(404).send(
        'Department account not found.'
      );
    }

    const allowedRecipient =
      recipient.role === 'dispatcher' ||
      (
        recipient.role === 'admin' &&
        ['super','other','accounts']
          .includes(
            String(
              recipient.admin_type || ''
            ).toLowerCase()
          )
      );

    if (!allowedRecipient) {
      return res.status(403).send(
        'This account is not part of the Finance communication path.'
      );
    }

    const messages = db.prepare(`
      SELECT
        m.id,
        m.sender_id,
        m.recipient_id,
        m.message,
        m.created_at,
        sender.name AS sender_name
      FROM messages m
      LEFT JOIN users sender
        ON sender.id=m.sender_id
      WHERE
        (
          m.sender_id=?
          AND m.recipient_id=?
        )
        OR
        (
          m.sender_id=?
          AND m.recipient_id=?
        )
      ORDER BY m.id ASC
    `).all(
      user.id,
      recipient.id,
      recipient.id,
      user.id
    );

    db.prepare(`
      UPDATE messages
      SET read_at=CURRENT_TIMESTAMP
      WHERE
        sender_id=?
        AND recipient_id=?
        AND read_at IS NULL
    `).run(
      recipient.id,
      user.id
    );

    const messageRows = messages.map(m => `
      <div
        style="
          margin-bottom:12px;
          padding:12px 14px;
          border-radius:10px;
          background:${
            Number(m.sender_id) === Number(user.id)
              ? 'rgba(212,175,55,.12)'
              : 'rgba(255,255,255,.06)'
          };
          border:1px solid rgba(255,255,255,.10);
        "
      >

        <div
          style="
            display:flex;
            justify-content:space-between;
            gap:12px;
          "
        >

          <strong>
            ${e(m.sender_name || 'User')}
          </strong>

          <small class="muted">
            ${e(m.created_at || '')}
          </small>

        </div>

        <div
          style="
            margin-top:7px;
            white-space:pre-wrap;
          "
        >
          ${e(m.message)}
        </div>

      </div>
    `).join('');

    res.send(
      page(
        'Department Chat',
        `
        <div class="page-head">

          <div>

            <div class="pill">
              ${e(
                recipient.role === 'dispatcher'
                  ? 'DISPATCHER'
                  : String(
                      recipient.admin_type ||
                      'ADMIN'
                    ).toUpperCase()
              )}
            </div>

            <h1>
              ${e(recipient.name || 'Department')}
            </h1>

            <p>
              ${e(recipient.email || '')}
            </p>

          </div>

        </div>

        <div class="card">

          <div
            style="
              max-height:420px;
              overflow-y:auto;
            "
          >
            ${
              messageRows ||
              `
              <p class="muted">
                No messages yet.
              </p>
              `
            }
          </div>

          <form
            method="POST"
            action="/finance/department-chat/${Number(
              recipient.id
            )}"
            style="margin-top:18px;"
          >

            <input
              type="hidden"
              name="_csrf"
              value="${csrf(req)}"
            >

            <textarea
              name="message"
              rows="4"
              required
              maxlength="5000"
              placeholder="Write a message..."
              style="
                width:100%;
                box-sizing:border-box;
              "
            ></textarea>

            <button
              type="submit"
              class="btn"
              style="margin-top:10px;"
            >
              Send Message
            </button>

          </form>

        </div>

        <div style="margin-top:18px;">

          <a
            class="btn ghost"
            href="/finance/department-chat"
          >
            Back to Department Communications
          </a>

        </div>
        `,
        req
      )
    );
  }
);

app.post(
  '/finance/department-chat/:id',
  requireRole('admin'),
  csrfCheck,
  (req, res) => {

    const user = req.session.user;

    if (
      user.admin_type !== 'finance' &&
      user.admin_type !== 'super'
    ) {
      return res.status(403).send(
        'Access denied.'
      );
    }

    const recipientId =
      Number(req.params.id);

    const message =
      String(req.body.message || '').trim();

    if (
      !Number.isInteger(recipientId) ||
      recipientId <= 0 ||
      !message
    ) {
      return res.status(400).send(
        'Recipient and message are required.'
      );
    }

    const recipient = db.prepare(`
      SELECT
        id,
        role,
        admin_type
      FROM users
      WHERE id=?
        AND active=1
      LIMIT 1
    `).get(recipientId);

    if (!recipient) {
      return res.status(404).send(
        'Department account not found.'
      );
    }

    const allowedRecipient =
      recipient.role === 'dispatcher' ||
      (
        recipient.role === 'admin' &&
        ['super','other','accounts']
          .includes(
            String(
              recipient.admin_type || ''
            ).toLowerCase()
          )
      );

    if (!allowedRecipient) {
      return res.status(403).send(
        'Invalid Finance communication recipient.'
      );
    }

    db.prepare(`
      INSERT INTO messages (
        sender_id,
        recipient_id,
        message
      )
      VALUES (?, ?, ?)
    `).run(
      user.id,
      recipient.id,
      message
    );

    res.redirect(
      `/finance/department-chat/${recipient.id}`
    );
  }
);
