app.post(
  '/admin/account-deactivation-requests/:id/approve',
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const requestId = Number(req.params.id);

    if (!Number.isInteger(requestId)) {
      return res.status(400).send(
        'Invalid deactivation request.'
      );
    }

    const request = db.prepare(`
      SELECT
        id,
        user_id,
        status
      FROM account_deactivation_requests
      WHERE id=?
    `).get(requestId);

    if (!request) {
      return res.status(404).send(
        'Deactivation request not found.'
      );
    }

    if (request.status !== 'pending') {
      return res.status(400).send(
        'This deactivation request has already been reviewed.'
      );
    }

    const rider = db.prepare(`
      SELECT
        id,
        role,
        active
      FROM users
      WHERE id=?
    `).get(request.user_id);

    if (!rider || rider.role !== 'rider') {
      return res.status(404).send(
        'Rider account not found.'
      );
    }

    const approveDeactivation = db.transaction(() => {

      db.prepare(`
        UPDATE account_deactivation_requests
        SET
          status='approved',
          reviewed_by=?,
          reviewed_at=CURRENT_TIMESTAMP,
          review_notes=?
        WHERE id=?
          AND status='pending'
      `).run(
        req.session.user.id,
        'Account deactivation approved by Locus Administration.',
        requestId
      );

      db.prepare(`
        UPDATE users
        SET
          active=0,
          online=0,
          deleted_at=NULL
        WHERE id=?
          AND role='rider'
      `).run(
        request.user_id
      );

      /*
        Remove any outstanding delivery offers so the
        deactivated rider cannot receive new work.
      */
      try {
        db.prepare(`
          UPDATE order_dispatches
          SET status='rejected'
          WHERE rider_id=?
            AND status='offered'
        `).run(request.user_id);
      } catch (err) {
        console.error(
          'Locus: failed to clear rider offers during deactivation:',
          err.message
        );
      }
    });

    approveDeactivation();

    res.redirect(
      '/admin/account-deactivation-requests'
    );
  }
);

app.post(
  '/admin/account-deactivation-requests/:id/reject',
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const requestId = Number(req.params.id);

    if (!Number.isInteger(requestId)) {
      return res.status(400).send(
        'Invalid deactivation request.'
      );
    }

    const request = db.prepare(`
      SELECT
        id,
        status
      FROM account_deactivation_requests
      WHERE id=?
    `).get(requestId);

    if (!request) {
      return res.status(404).send(
        'Deactivation request not found.'
      );
    }

    if (request.status !== 'pending') {
      return res.status(400).send(
        'This deactivation request has already been reviewed.'
      );
    }

    db.prepare(`
      UPDATE account_deactivation_requests
      SET
        status='rejected',
        reviewed_by=?,
        reviewed_at=CURRENT_TIMESTAMP,
        review_notes=?
      WHERE id=?
        AND status='pending'
    `).run(
      req.session.user.id,
      'Account deactivation request rejected by Locus Administration.',
      requestId
    );

    res.redirect(
      '/admin/account-deactivation-requests'
    );
  }
);

