app.post(
  '/admin/promotions/:audience?',
  promotionUpload.single('media'),
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const title =
      String(req.body.title || '').trim();

    const message =
      String(req.body.message || '').trim();

 const requestedAudience =
  String(req.params.audience || '').trim();

const audience =
  requestedAudience === 'business'
    ? 'business'
    : requestedAudience === 'all'
      ? 'all'
      : String(req.body.audience || 'customer').trim();
    const mediaType =
      String(req.body.media_type || 'none').trim();

    const allowedAudiences = [
      'customer',
      'rider',
      'business',
      'all'
    ];

    const allowedMediaTypes = [
      'none',
      'image',
      'video'
    ];

    if (
      title.length < 2 ||
      title.length > 120 ||
      message.length < 2 ||
      message.length > 1000 ||
      !allowedAudiences.includes(audience) ||
      !allowedMediaTypes.includes(mediaType)
    ) {
      return res.redirect(
      req.query.audience === 'business'
        ? '/admin/promotions/business'
        : req.query.audience === 'all'
          ? '/admin/promotions/all'
          : '/admin/promotions'
    );
    }

    let mediaPath = null;

    if (mediaType === 'image' || mediaType === 'video') {

      if (!req.file) {
        return res.redirect('/admin/promotions');
      }

      mediaPath =
        `/uploads/promotions/${req.file.filename}`;
    }

    db.prepare(`
      INSERT INTO promotional_messages(
        title,
        message,
        active,
        created_by,
        audience,
        media_type,
        media_path
      )
      VALUES(?,?,1,?,?,?,?)
    `).run(
      title,
      message,
      req.session.user.id,
      audience,
      mediaType,
      mediaPath
    );

res.redirect(
  requestedAudience === 'business'
    ? '/admin/promotions/business'
    : '/admin/promotions'
);
  }
);
app.post(
  '/admin/promotions/:id/toggle',
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const id =
      Number(req.params.id);

    if (!Number.isInteger(id)) {
      return res.redirect(
  req.query.audience === 'business'
    ? '/admin/promotions/business'
    : req.query.audience === 'all'
      ? '/admin/promotions/all'
      : '/admin/promotions'
);
    }

    db.prepare(`
      UPDATE promotional_messages
      SET
        active =
          CASE
            WHEN active=1 THEN 0
            ELSE 1
          END,
        updated_at=CURRENT_TIMESTAMP
      WHERE id=?
    `).run(id);

    res.redirect(
      req.query.audience === 'business'
        ? '/admin/promotions/business'
        : req.query.audience === 'all'
          ? '/admin/promotions/all'
          : '/admin/promotions'
    );
  }
);

app.post(
  '/admin/promotions/:id/delete',
  csrfCheck,
  requireRole('admin'),
  (req, res) => {

    const id =
      Number(req.params.id);

    if (!Number.isInteger(id)) {
      return res.redirect('/admin/promotions');
    }

    const promotion = db.prepare(`
      SELECT media_path
      FROM promotional_messages
      WHERE id=?
    `).get(id);

    if (promotion?.media_path) {
      const relativePath = promotion.media_path.replace(/^\/+/, "");
      const fullPath = path.resolve(__dirname, relativePath);
      const promotionsDir = path.resolve(__dirname, "uploads", "promotions");

      if (
        fullPath.startsWith(promotionsDir + path.sep) &&
        fs.existsSync(fullPath)
      ) {
        fs.unlinkSync(fullPath);
      }
    }

    db.prepare(`
      DELETE FROM promotional_messages
      WHERE id=?
    `).run(id);

    res.redirect(
  req.query.audience === 'business'
    ? '/admin/promotions/business'
    : req.query.audience === 'all'
      ? '/admin/promotions/all'
      : '/admin/promotions'
);
  }
);



